    setCallbacklogin() {
      FNSDK.invoke("setCallbackloginState", function(code, msg, data) {
        console.log("liu-FNSDK setCallbackloginState callback ", code, msg, data);
        var uid, name, ext;
        switch (code) {
          case FNCode.SUCC:
            console.log("liu-FNSDK login successful" + JSON.stringify(data));
            uid = data.uid;
            name = data.name;
            ext = data.ext;
            androidData.sdkLoginUid = uid;
            androidData.sdkLoginName = name;
            androidData.sdkLoginExt = ext;
            androidData.sdkLoginInfo = { code: "loginSucc" };
            break;
          case FNCode.FAIL:
            console.log("liu-FNSDK login fail", msg);
            androidData.sdkLoginInfo = { code: "loginFail" };
            break;
          case FNCode.CANCEL:
            break;
          case 3:
            console.log("liu-FNSDK ChangeAccount  successful" + JSON.stringify(data));
            uid = data.uid;
            name = data.name;
            ext = data.ext;
            ext = typeof ext == "string" ? JSON.parse(ext) : ext;
            androidData.sdkLoginUid = uid;
            androidData.sdkLoginName = name;
            androidData.sdkLoginExt = ext;
            break;
          case 5:
            console.log("liu-FNSDK QuitAccount  successful" + JSON.stringify(data));
            break;
          default:
            break;
        }
      });
    }
