    sendWeWorkMsg(url, sendMsg, isMsgBefore = true) {
      let xhr = new Laya.HttpRequest();
      xhr.http.timeout = 6e3;
      let data = {};
      data["msgtype"] = "text";
      let date = /* @__PURE__ */ new Date();
      let t = `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()} ${date.getHours()}:${date.getMinutes()}:${date.getSeconds()}:${date.getTime() % 1e3}`;
      var beforeMsg = "";
      if (isMsgBefore) {
        beforeMsg = sendMsg + "\n";
      }
      const now = t;
      const playerName = PlayerData.ins().name;
      const playerId = PlayerData.ins().playerId;
      const gameChannel = androidData.sdkChannel;
      const deviceModel = androidData.sdkDeviceName;
      const playerLevel = PlayerData.ins().level;
      const appVersion = androidData.appVerson;
      const resourceVersion = AppConfig.getFullVersion();
      let msg = `${beforeMsg}时间:${now}
名称: ${playerName}
玩家id:${playerId}
平台:${gameChannel}
机型:${deviceModel}
等级:${playerLevel}`;
      msg = `${msg}
APP版本号:${appVersion}
资源版本号:${resourceVersion}`;
      if (isMsgBefore == false) {
        msg = msg + "\n" + sendMsg;
      }
      data["text"] = { content: msg };
      xhr.http.withCredentials = true;
      xhr.send(url, JSON.stringify(data), "post", "json", ["Content-Type", "application/json", "Access-Control-Allow-Origin", "*"]);
    }
