    parseQuery(search) {
      const result = {};
      if (!search) {
        return result;
      }
      const query = search.startsWith("?") ? search.substring(1) : search;
      if (!query) {
        return result;
      }
      query.split("&").forEach((pair) => {
        if (!pair) {
          return;
        }
        const idx = pair.indexOf("=");
        const rawKey = idx >= 0 ? pair.substring(0, idx) : pair;
        const rawValue = idx >= 0 ? pair.substring(idx + 1) : "";
        const key = decodeURIComponent(rawKey || "");
        if (!key) {
          return;
        }
        result[key] = decodeURIComponent(rawValue || "");
      });
      return result;
    }
    parseShareQuery(search) {
      const allQuery = this.parseQuery(search);
      const packedQuery = allQuery[_DefaultPlatform.WEB_SHARE_QUERY_KEY];
      if (!packedQuery) {
        return {};
      }
      return this.parseQuery(decodeURIComponent(packedQuery));
    }
