    //日志
    DoFNSDKLog(type, param) {
      switch (type) {
        case 1:
          let len = this.SomethingTaskList.length;
          for (let index = len - 1; index >= 0; index--) {
            let task2 = this.SomethingTaskList[index];
            this.DoFNSDKLog(task2.key, task2.param);
            this.SomethingTaskList.splice(index, 1);
          }
          break;
        case 2:
          if (this.sdkInitFinished) {
            param.serverId = "1";
            param.serverName = AppConfig.wsAddress;
            FNSDK.invoke("logCreateRole", param);
          } else {
            param.serverId = "1";
            param.serverName = AppConfig.wsAddress;
            this.SomethingTaskList.push({ key: 2, param });
          }
          break;
        case 3:
          if (this.sdkInitFinished) {
            param.serverId = "1";
            FNSDK.invoke("logRoleLevel", param);
          } else {
            param.serverId = "1";
            this.SomethingTaskList.push({ key: 3, param });
          }
          break;
        case 4:
          if (this.sdkInitFinished) {
            if (!this._logEnterGame) {
              this._logEnterGame = true;
              param.serverId = "1";
              param.serverName = AppConfig.wsAddress;
              FNSDK.invoke("logEnterGame", param);
            }
          } else {
            param.serverId = "1";
            param.serverName = AppConfig.wsAddress;
            this.SomethingTaskList.push({ key: 4, param });
          }
          break;
        case 5:
          if (this.sdkInitFinished) {
            param.serverId = "1";
            FNSDK.invoke("logSelectServer", param);
          } else {
            param.serverId = "1";
            this.SomethingTaskList.push({ key: 5, param });
          }
          break;
        case 6:
          if (this.sdkInitFinished) {
            let param2 = {};
            FNSDK.invoke("logFinishGuiderEvent", param2);
          } else {
            this.SomethingTaskList.push({ key: 6, param: {} });
          }
          break;
        default:
          break;
      }
    }
