    login() {
      return new Promise((resolve, reject) => __async(this, null, function* () {
        if (!this.isLogined) {
          this.sdkLogin();
        }
        yield this.waitFor(
          () => this.sdkLoginCode != null && this.sdkGid != null
        );
        if (this.sdkLoginCode.code == "loginFail")
          reject(0);
        else
          resolve(this.sdkInfo.sdkLoginUid);
      }));
    }
