    pay(payInfo) {
      let _callbackInfo = `${payInfo.orderId}`;
      var productInfo = {
        //
        price: payInfo.money,
        // 实际充值金额，单位：元。这个price不会和productCount和rate重新计算，这个值填多少就充多少元
        productId: payInfo.rechargeid,
        // 商品id，必填，不同商品的id不能相同，id编号从1开始
        productName: payInfo.name,
        // 商品名称。
        productDesc: payInfo.name,
        // 商品描述。
        productCount: "1",
        // 商品数量。会和productName一起显示给用户看，不参与price计算。表示 productCount 份 productName
        rate: "100",
        // 人民币和游戏币兑换比例（如 1元 = 10元宝）。仅显示给用户看，不参与price计算
        coinName: "钻石",
        // 游戏内使用货币的名称，如元宝、钻石等
        callbackInfo: _callbackInfo,
        // 研发自定义的透传信息。sdk充值完成后，蜂鸟服务端回调给游戏服务端通知发货时，会原样返回给游戏
        uid: this.sdkInfo.sdkLoginUid,
        // uid
        serverId: "1",
        // 服务器ID
        roleName: payInfo.NameReplace,
        // 角色名
        roleId: payInfo.PlayerId,
        // 角色id
        level: payInfo.Level,
        // 角色等级
        sendMessageImg: `${Laya.URL.basePath}/share/charge.png`,
        sendMessageTitle: "充值"
      };
      console.log("fnsdk pay  ", productInfo);
      FNSDK.invoke("pay", productInfo, function(code, msg, data) {
        console.log("FNSDK pay callback " + JSON.stringify(data));
        let orderData = Laya.LocalStorage.getItem("pay_order_list");
        if (orderData && orderData.length > 0) {
          let orderlist = JSON.parse(orderData);
          for (let i = 0; i < orderlist.length; i++) {
            if (orderlist[i].callbackInfo == productInfo.callbackInfo) {
              orderlist.splice(i, 1);
              console.log("FNSDK pay 回调删除记录 " + productInfo.callbackInfo);
              break;
            }
          }
          orderData = JSON.stringify(orderlist);
          Laya.LocalStorage.setItem("pay_order_list", orderData);
          console.log("FNSDK pay 回调删除记录后 " + orderData);
        }
        if (code == FNCode.SUCC) {
        } else {
        }
      });
      return new Promise((resolve, reject) => {
        wx.requestMidasPayment({
          mode: payInfo.mode,
          env: payInfo.env,
          offerId: payInfo.offerId,
          currencyType: "CNY",
          platform: this.systemInfo.platform,
          buyQuantity: payInfo.buyQuantity,
          zoneId: payInfo.zoneId,
          success: function(res) {
            resolve(1);
          },
          fail: function(code) {
            if (code == -1)
              resolve(3);
            else
              resolve(code);
          },
          complete: function(res) {
          }
        });
      });
    }
