    showRewardedVideoAd(success, fail, ad_id) {
      if (typeof wx.createRewardedVideoAd === "function") {
        let videoAd = wx.createRewardedVideoAd({
          adUnitId: ad_id,
          multiton: false
        });
        console.log("创建激励视频showRewardedVideoAd:" + ad_id);
        let onClose = function(res) {
          videoAd.offClose(onClose);
          videoAd.offError(onError);
          videoAd.offLoad(onLoad);
          if (res && res.isEnded || res === void 0) {
            success(true);
          } else {
            success(false);
          }
          Reporter.SendEvent("video_onClose", "曝光");
        };
        let onError = function(error) {
          console.log(error, "视频播放错误信息");
          videoAd.offClose(onClose);
          videoAd.offError(onError);
          fail && fail();
        };
        let onLoad = function() {
          Reporter.SendEvent("video_onLoad", "加载完成");
        };
        videoAd.onClose(onClose);
        videoAd.onError(onError);
        videoAd.onLoad(onLoad);
        videoAd.show().catch(function() {
          videoAd.load().then(function() {
            return videoAd.show();
          }).catch(function() {
            videoAd.offClose(onClose);
            videoAd.offError(onError);
            videoAd.offLoad(onLoad);
            fail && fail(-1);
          });
        });
      } else {
        fail && fail();
      }
    }
    onUpdate() {
      let keys = Object.keys(this._customInfoArr);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        const value = this._customInfoArr[key];
        if (!!value && value.ins && value.ins.isShow()) {
          if (Date.now() - value.times >= 3e4) {
            value.ins && value.ins.destroy();
            value.ins = null;
            value.times = 0;
            this.showCustomAd(value.x, value.y, value.adUnitId, value.type, value.canShow);
          }
        }
      }
    }
    showCustomAd(left, right, ad_id, type, delay, canShow = true) {
      if (DeviceUtils.ins().compareVersion(this.systemInfo.SDKVersion, "2.11.1") < 0) {
        return Promise.resolve(0);
      }
      if (typeof wx.createCustomAd !== "function") {
        return Promise.resolve(0);
      }
      let info = this._customInfoArr[type];
      if (!info) {
        info = { times: 0, x: left, y: right, adUnitId: ad_id, type, canShow: true };
        this._customInfoArr[type] = info;
      } else {
        info.times = Date.now();
      }
      let self = this;
      info.canShow = canShow;
      return new Promise((resolve, reject) => {
        if (!info.ins) {
          let ins = wx.createCustomAd({
            adUnitId: ad_id,
            style: {
              left,
              top: right,
              width: 300,
              fixed: false
            },
            adIntervals: 60
          });
          let onError = function(err) {
            console.log("原生模板广告调用错误码" + ad_id, type, err);
            ins.offError(onError);
            ins.offLoad(onLoad);
            ins.offClose(onClose);
            ins.offHide(onHide);
            resolve(0);
          };
          let onClose = function() {
            console.log("原生模板广告点击关闭");
            ins.offError(onError);
            ins.offLoad(onLoad);
            ins.offClose(onClose);
            ins.offHide(onHide);
          };
          let onLoad = function() {
            if (info.canShow && !ins.isShow()) {
              Laya.timer.once(delay, self, () => {
                info.canShow && ins.show().then(() => {
                  if (!info.canShow && info.ins.isShow()) {
                    this.hideCustomAd(type);
                    resolve(0);
                  } else {
                    if (info.times == 0) {
                      info.times = Date.now();
                    }
                    resolve(1);
                  }
                }).catch(() => {
                  ins && ins.destroy();
                  info.ins = null;
                  self._customInfoArr[type] = null;
                  resolve(0);
                });
              });
            }
          };
          let onHide = function() {
            info.ins && info.ins.destroy();
            info.ins = null;
            self.showCustomAd(left, right, ad_id, type, delay, false);
          };
          ins.onError(onError);
          ins.onLoad(onLoad);
          ins.onClose(onClose);
          ins.onHide(onHide);
          info.ins = ins;
        } else {
          if (info.canShow && info.ins && !info.ins.isShow()) {
            Laya.timer.once(delay, self, () => {
              info.canShow && info.ins.show().then(() => {
                if (!info.canShow && info.ins.isShow()) {
                  this.hideCustomAd(type);
                  resolve(0);
                } else {
                  if (info.times == 0) {
                    info.times = Date.now();
                  }
                  resolve(1);
                }
              }).catch(() => {
                info.ins && info.ins.destroy();
                info.ins = null;
                self._customInfoArr[type] = null;
                resolve(0);
              });
            });
          }
          ;
        }
      });
    }
    hideCustomAd(type) {
      if (this._customInfoArr[type]) {
        const info = this._customInfoArr[type];
        info.canShow = false;
        if (info.ins) {
          info.ins.hide().catch(() => {
            info.ins && info.ins.destroy();
            info.ins = null;
            this._customInfoArr[type] = null;
          });
        }
      }
    }
    hideAllCustomAd() {
      let keys = Object.keys(this._customInfoArr);
      for (let i = 0; i < keys.length; i++) {
        const key = keys[i];
        let info = this._customInfoArr[key];
        if (!info)
          continue;
        if (info.ins && info.ins.isShow()) {
          info.ins.hide().catch(() => {
            info.ins && info.ins.destroy();
            info.ins = null;
            this._customInfoArr[key] = null;
          });
        }
      }
    }
