    showBannerAd(delay, alignV, alignH, adUnitId, type, time) {
      if (type == 0) {
        return this.showBannerAd0(delay, alignV, alignH, adUnitId);
      } else if (type == 1) {
        return this.showBannerAd1(delay, alignV, alignH, adUnitId, time);
      }
      return Promise.resolve(0);
    }
    hideBannerAd(type, adUnitId, time) {
      if (type == 0) {
        return this.hideBannerAd0(time, adUnitId);
      } else if (type == 1) {
        return this.hideBannerAd1(adUnitId);
      }
    }
    showBannerAd0(delay, alignV, alignH, adUnitId) {
      let self = this;
      let obj = this._bannerObj[adUnitId];
      return new Promise((resolve, reject) => {
        if (obj) {
          obj.canShow = true;
          Laya.timer.once(delay, self, () => {
            if (obj.canShow && obj.bannerAd) {
              obj.bannerAd.show().then(function() {
                obj.times++;
                resolve(1);
              }).catch(function() {
                obj.bannerAd.destroy();
                obj.bannerAd = null;
                delete self._bannerObj[adUnitId];
                resolve(0);
              });
            } else {
              resolve(0);
            }
          });
        } else {
          this._bannerObj[adUnitId] = { times: 0, alignV, alignH, canShow: true };
          obj = this._bannerObj[adUnitId];
          obj.bannerAd = wx.createBannerAd({
            adUnitId,
            style: {
              left: 0,
              top: 0,
              width: 300,
              height: 100
            },
            adIntervals: 60
          });
          let onError = function(err) {
            console.log("广告调用错误码", err);
            if (obj.bannerAd) {
              obj.bannerAd.offResize(onResize);
              obj.bannerAd.offError(onError);
              obj.bannerAd.offLoad(onLoad);
              obj.bannerAd.destroy();
              obj.bannerAd = null;
            }
            delete self._bannerObj[adUnitId];
            resolve(0);
          };
          let onResize = function() {
            if (!obj.bannerAd)
              return;
            if (alignV == Laya.Stage.ALIGN_TOP) {
              obj.bannerAd.style.top = 0;
            } else if (alignV == Laya.Stage.ALIGN_MIDDLE) {
              obj.bannerAd.style.top = (self.clientHeight - obj.bannerAd.style.realHeight) / 2;
            } else if (alignV == Laya.Stage.ALIGN_BOTTOM) {
              obj.bannerAd.style.top = self.clientHeight - obj.bannerAd.style.realHeight;
            }
            if (alignH == Laya.Stage.ALIGN_LEFT) {
              obj.bannerAd.style.left = 0;
            } else if (alignH == Laya.Stage.ALIGN_CENTER) {
              obj.bannerAd.style.left = (self.clientWidth - obj.bannerAd.style.realWidth) / 2;
            } else if (alignH == Laya.Stage.ALIGN_RIGHT) {
              obj.bannerAd.style.left = self.clientWidth - obj.bannerAd.style.realWidth;
            }
          };
          let onLoad = function() {
            if (obj.canShow) {
              Laya.timer.once(delay, self, () => {
                if (obj.canShow && obj.bannerAd) {
                  obj.bannerAd.show().then(function() {
                    obj.times++;
                    resolve(1);
                  }).catch(function() {
                    obj.bannerAd.destroy();
                    obj.bannerAd = null;
                    delete self._bannerObj[adUnitId];
                    resolve(0);
                  });
                } else {
                  resolve(0);
                }
              });
            } else {
              obj.bannerAd && obj.bannerAd.hide();
              resolve(0);
            }
          };
          obj.bannerAd.onResize(onResize);
          obj.bannerAd.onError(onError);
          obj.bannerAd.onLoad(onLoad);
        }
      });
    }
    hideBannerAd0(time, adUnitId) {
      let obj = this._bannerObj[adUnitId];
      if (obj && obj.bannerAd) {
        obj.bannerAd.hide();
        obj.canShow = false;
        if (obj.times >= time) {
          obj.bannerAd.destroy();
          obj.bannerAd = null;
          delete this._bannerObj[adUnitId];
        }
      }
    }
    showBannerAd1(delay, alignV, alignH, adUnitId, time) {
      let self = this;
      let obj = this._bannerObj[adUnitId];
      return new Promise((resolve, reject) => {
        if (obj && Date.now() - obj.times < time) {
          obj.canShow = true;
          Laya.timer.once(delay, self, () => {
            if (obj.canShow && obj.bannerAd) {
              obj.bannerAd.show().then(function() {
                if (obj.times == 0)
                  obj.times = Date.now();
                resolve(1);
              }).catch(function() {
                obj.bannerAd.destroy();
                obj.bannerAd = null;
                delete self._bannerObj[adUnitId];
                resolve(0);
              });
            } else {
              resolve(0);
            }
          });
        } else {
          if (obj && obj.bannerAd) {
            obj.bannerAd.destroy();
            obj.bannerAd = null;
          }
          this._bannerObj[adUnitId] = { times: 0, alignV, alignH, canShow: true };
          obj = this._bannerObj[adUnitId];
          obj.bannerAd = wx.createBannerAd({
            adUnitId,
            style: {
              left: 0,
              top: 0,
              width: 300,
              height: 100
            },
            adIntervals: 60
          });
          let onError = function(err) {
            console.log("广告调用错误码", err);
            if (obj.bannerAd) {
              obj.bannerAd.offResize(onResize);
              obj.bannerAd.offError(onError);
              obj.bannerAd.offLoad(onLoad);
              obj.bannerAd.destroy();
              obj.bannerAd = null;
            }
            delete self._bannerObj[adUnitId];
            resolve(0);
          };
          let onResize = function() {
            if (!obj.bannerAd)
              return;
            if (alignV == Laya.Stage.ALIGN_TOP) {
              obj.bannerAd.style.top = 0;
            } else if (alignV == Laya.Stage.ALIGN_MIDDLE) {
              obj.bannerAd.style.top = (self.clientHeight - obj.bannerAd.style.realHeight) / 2;
            } else if (alignV == Laya.Stage.ALIGN_BOTTOM) {
              obj.bannerAd.style.top = self.clientHeight - obj.bannerAd.style.realHeight;
            }
            if (alignH == Laya.Stage.ALIGN_LEFT) {
              obj.bannerAd.style.left = 0;
            } else if (alignH == Laya.Stage.ALIGN_CENTER) {
              obj.bannerAd.style.left = (self.clientWidth - obj.bannerAd.style.realWidth) / 2;
            } else if (alignH == Laya.Stage.ALIGN_RIGHT) {
              obj.bannerAd.style.left = self.clientWidth - obj.bannerAd.style.realWidth;
            }
          };
          let onLoad = function() {
            if (obj.canShow) {
              Laya.timer.once(delay, self, () => {
                if (obj.canShow && obj.bannerAd) {
                  obj.bannerAd.show().then(function() {
                    if (obj.times == 0)
                      obj.times = Date.now();
                    resolve(1);
                  }).catch(function() {
                    obj.bannerAd.destroy();
                    obj.bannerAd = null;
                    delete self._bannerObj[adUnitId];
                    resolve(0);
                  });
                } else {
                  resolve(0);
                }
              });
            } else {
              obj.bannerAd && obj.bannerAd.hide();
              resolve(0);
            }
          };
          obj.bannerAd.onResize(onResize);
          obj.bannerAd.onError(onError);
          obj.bannerAd.onLoad(onLoad);
        }
      });
    }
    hideBannerAd1(adUnitId) {
      let obj = this._bannerObj[adUnitId];
      if (obj && obj.bannerAd) {
        obj.bannerAd.hide();
        obj.canShow = false;
      }
    }
    hideBannerAd2(adUnitId) {
      let obj = this._bannerObj[adUnitId];
      if (obj && obj.bannerAd) {
        obj.bannerAd.hide();
        obj.canShow = false;
        obj.bannerAd.destroy();
        obj.bannerAd = null;
        delete this._bannerObj[adUnitId];
      }
    }
