    get systemInfo() {
      if (null == this.__systemInfo) {
        this.__systemInfo = wx.getSystemInfoSync();
      }
      return this.__systemInfo;
    }
    get clientWidth() {
      return this.systemInfo.screenWidth;
    }
    get clientHeight() {
      return this.systemInfo.screenHeight;
    }
    get SDKVersion() {
      return this.systemInfo.SDKVersion;
    }
    getMachineInfo() {
      let info = this.systemInfo;
      let ret = new cmd.client_machine_info();
      ret.source = Laya.Browser.onIOS ? 2 : 1;
      ret.affiliate = 0;
      ret.client_version = info.version;
      ret.phone_type = info.model;
      ret.phone_version = info.system;
      ret.ratio = info.screenWidth + ":" + info.screenHeight;
      ret.service = info.platform;
      ret.udid = "";
      ret.machineid = info.SDKVersion;
      ret.machine_name = info.brand;
      return ret;
    }
