    createWorker() {
      if (!this.enableWorker) {
        return;
      }
      if (this._worker) {
        return this._worker;
      }
      let worker2 = wx.createWorker("workers/workerbundle.js", { useExperimentalWorker: true });
      if (typeof worker2.onProcessKilled !== "undefined") {
        worker2.onProcessKilled(this.onProcessKilled.bind(this));
      }
      if (!worker2) {
        const info2 = this.systemInfo;
      }
      worker2.postMessage({ type: "initwasm", data: { type: "WXWebAssembly", path: "jslib/laya.physics3D.wasm.wasm" } });
      this._worker = worker2;
      return this._worker;
    }
    onProcessKilled() {
      console.log("onProcessKilled");
      this._worker = null;
    }
    terminateWorker() {
      if (this._worker) {
        this._worker.terminate();
        this._worker = null;
      }
    }
