  // src/script/start/Hook.ts
  var Hook = class {
    static init() {
      Laya.LocalStorage.getJSON = function(key) {
        const ret = Laya.PAL.storage.getItem(key);
        if (!ret) {
          return null;
        }
        return JSON.parse(ret);
      };
      const rawUpdate = Laya.timer["_update"];
      Laya.timer["_update"] = () => {
        try {
          rawUpdate.apply(Laya.timer);
        } catch (e) {
          ErrorReportManager.ins().reportError(e);
        }
      };
      const ITEM_LAYOUT = 4;
      Laya.Delegate.prototype["invoke"] = function(...args) {
        if (this._flag != 0)
          return;
        this._flag = 1;
        let arr = this._items;
        let cnt = arr.length;
        for (let i = 0; i < cnt; i += ITEM_LAYOUT) {
          if (arr[i + 3] === 0)
            continue;
          let fixedArgs = arr[i + 2];
          try {
            if (fixedArgs != null)
              arr[i].call(arr[i + 1], ...fixedArgs, ...args);
            else
              arr[i].call(arr[i + 1], ...args);
          } catch (err) {
            ErrorReportManager.ins().reportError(err);
          }
          if (arr[i + 3] === 2) {
            arr[i + 3] = 0;
            this._flag = 2;
          }
        }
        if (this._flag === 2) {
          let cnt2 = arr.length;
          let i = 0;
          while (i < cnt2) {
            if (arr[i + 3] === 0) {
              arr.splice(i, ITEM_LAYOUT);
              cnt2 -= ITEM_LAYOUT;
              continue;
            } else
              i += ITEM_LAYOUT;
          }
        }
        this._flag = 0;
      };
    }
  };

