  var AdModule = class extends BaseModule {
    constructor() {
      super(...arguments);
      /**
       * 视频频控限制
       */
      this._isCanVideo = true;
      /**
       * 视频领奖回包回调
       */
      this.videoWachS2cCallBack = /* @__PURE__ */ new Map();
    }
    onInit() {
      this.registerMessage(cmd.video_watch_s2c, this.video_watch_s2c);
    }
    onLogin(toc) {
      AdManager.ins().init();
    }
    onAfterLogin(s2c) {
      AdManager.ins().syncVideoWatchCountList(s2c.tdvideo2num || []);
    }
    onRegisterView() {
    }
    onCrossDay(s2c) {
    }
    /**
     * 看视频完统一接口
     * @param videoId 视频点id 枚举
     * @param ext json字符串(对应功能协议需要的字段)
     * @param type 1-使用广告券 2-钻石跳过(华为鸿蒙)
     * @param callback 收到回包回调
     */
    video_watch_c2s(videoId, ext, type = 0, callback) {
      let time = 300;
      if (this._isCanVideo) {
        this._isCanVideo = false;
        let msg = new cmd.video_watch_c2s();
        msg.video_id = videoId;
        msg.ext = ext;
        if (type) {
          msg.skip_type = type;
        } else {
          let num = CurrencyData.ins().getCurrency(20 /* AD_TICKET */);
          if (num > 0) {
            msg.skip_type = 1;
          }
        }
        if (callback) {
          this.videoWachS2cCallBack.set(videoId, callback);
        }
        NetService.send(msg);
        Laya.timer.once(time, this, () => {
          this._isCanVideo = true;
        }, null, false);
      } else {
        let str = type == 2 ? "点击太快" : `看视频太快`;
        TipsManager.ins().showMessageTips(str);
        Laya.timer.once(time, this, () => {
          this._isCanVideo = true;
        }, null, false);
      }
    }
    /**
     * 视频领奖回包
     * @param toc 
     */
    video_watch_s2c(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      let callBack = this.videoWachS2cCallBack.get(toc.video_id);
      if (callBack) {
        callBack();
        this.videoWachS2cCallBack.delete(toc.video_id);
      }
    }
  };

  // src/script/module/ad/utils/AdUtils.ts
  var AdUtils = class {
    /**
     * 获取广告与分享图标(兼容html与img)
     * @param adId 广告id
     * @param videoIcon 视频图标
     * @returns 图标html路径
     */
    static checkVideoIcon(adId, videoIcon = null) {
      const adType = AdManager.ins().getAdType(adId);
      console.log(`广告id${adId}--类型${adType === 1 /* Share */ ? "分享" : "视频"}`);
      let str = UIUtils.getImageUrl("media", adType === 1 /* Share */ ? "ui_icon_share2_n" : "ui_qd_sp");
      if (videoIcon) {
        videoIcon.src = str;
      }
      return str;
    }
  };

  // src/script/module/player/PlayerManager.ts
  var PlayerManager = class extends BaseClass {
    constructor() {
      super(...arguments);
      /** 简单玩家信息 */
      this._simplePlayerInfos = {};
      this._simplePlayerInfoBatchList = [];
      this._simplePlayerInfoRequested = false;
    }
    /**
     * 请求玩家信息
     * @param userId 用户id
     */
    requestSimplePlayerInfo(userId) {
      if (this._simplePlayerInfoBatchList.indexOf(userId) !== -1) {
        return;
      }
      this._simplePlayerInfoBatchList.push(userId);
      if (this._simplePlayerInfoRequested) {
        return;
      }
      this._simplePlayerInfoRequested = true;
      Laya.timer.once(300, this, this.flushSimplePlayerInfoRequest);
    }
    flushSimplePlayerInfoRequest() {
      if (this._simplePlayerInfoBatchList.length > 0) {
        PlayerProtoUtils.player_info_query_simple_req_tos(this._simplePlayerInfoBatchList);
      }
      this._simplePlayerInfoRequested = false;
      this._simplePlayerInfoBatchList = [];
    }
    /** 内部使用 */
    _player_info_query_simple_req_toc(toc) {
      if (toc.info_list.length <= 0) {
        return;
      }
      for (let temp of toc.info_list) {
        this._simplePlayerInfos[temp.userid] = temp;
      }
      EventEngine.dispatchEvent(42 /* PlayerProfileChange */);
      EventEngine.dispatchEvent(44 /* PlayerAppearanceChange */);
    }
    /**
     * 获取玩家信息
     * @param userId 用户id
     */
    getSimplePlayerInfo(userId) {
      return this._simplePlayerInfos[userId];
    }
    /**
     * 请求变更性别
     */
    changeSex() {
      const changeSexCount = PlayerData.ins().changeSexCount;
      if (changeSexCount === 0) {
        TipsManager.ins().showMessageBox({
          title: "切换性别",
          content: "首次切换性别免费哦",
          bottomContent: "首次免费",
          title_ok: "切换",
          visible_cancel: false,
          callback_ok: () => {
            PlayerProtoUtils.player_set_sex_req_tos();
          }
        });
      } else if (changeSexCount === 1) {
        let content = "";
        if (PlayerData.ins().sex === 1 /* MAN */) {
          content = "免费切换成女性";
        } else {
          content = "免费切换成男性";
        }
        TipsManager.ins().showMessageBox({
          title: "切换性别",
          content,
          title_ok: UIUtils.getHtmlPath(AdUtils.checkVideoIcon(FuncEntryData.ins().getFuncAdId(10100701 /* home_page */, "ad"))) + `切换`,
          visible_cancel: false,
          callback_ok: () => {
            const adId = FuncEntryData.ins().getFuncAdId(10100701 /* home_page */, "ad");
            let jsoninfo = { "video_id": adId, "sex": PlayerData.ins().sex === 1 /* MAN */ ? 2 /* WOMEN */ : 1 /* MAN */ };
            AdManager.ins().showAd({
              ad_id: adId,
              ext: JSON.stringify(jsoninfo)
            });
          }
        });
      } else {
        let content = "";
        if (PlayerData.ins().sex === 1 /* MAN */) {
          content = "当前性别为：男，确定要消耗1张性别切换卡切换到女性吗？";
        } else {
          content = "当前性别为：女，确定要消耗1张性别切换卡切换到男性吗？";
        }
        TipsManager.ins().showMessageBox({
          title: "切换性别",
          content,
          visible_cancel: false,
          bottomContent: `本次修改花费${BagUtils.getThingHtmlIconPath(600009 /* CHANGE_SEX_CARD */, 48, 48)}x1`,
          title_ok: "切换",
          callback_ok: () => {
            if (BagUtils.isEnough(600009 /* CHANGE_SEX_CARD */, 1)) {
              PlayerProtoUtils.player_set_sex_req_tos();
            } else {
              ShopManager.ins().buyItem(600009 /* CHANGE_SEX_CARD */);
            }
          }
        });
      }
    }
    /**
     * 修改名称
     */
    updateNick() {
      const setNickCount = PlayerData.ins().nickSetCount;
      const taskCfg = ConfigUtil.Tables.comm_config.get(506);
      if (setNickCount === 0) {
        TipsManager.ins().showInputBox({
          title: "修改名称",
          prompt: "请输入新的名称(最多6个字)",
          maxChars: 6,
          boxHeight: 350,
          content: "首次改名免费",
          okStyle: {
            title: "修改"
          },
          restrict: "a-zA-Z,\\u4e00-\\u9fa5,0-9,*",
          callback_ok: (newName) => {
            if (StringUtils.isNullOrEmpty(newName)) {
              TipsManager.ins().showMessageTips("名称为空！");
              return false;
            }
            PlayerProtoUtils.send_set_nick_req(newName, 1);
          }
        });
      } else if (setNickCount <= taskCfg.int_value) {
        TipsManager.ins().showInputBox({
          title: "修改名称",
          prompt: "请输入新的名称(最多6个字)",
          maxChars: 6,
          boxHeight: 350,
          content: "看视频免费修改",
          okStyle: {
            btnSrc: "ui_btn_ty_r2",
            title: UIUtils.getHtmlPath(AdUtils.checkVideoIcon(FuncEntryData.ins().getFuncAdId(10100701 /* home_page */, "ad"))) + `修改`,
            titleStrokeColor: "#CD4202"
          },
          restrict: "a-zA-Z,\\u4e00-\\u9fa5,0-9,*",
          callback_ok: (newName) => {
            if (StringUtils.isNullOrEmpty(newName)) {
              TipsManager.ins().showMessageTips("名称为空！");
              return false;
            }
            let jsoninfo = { "nick": newName, "type": 1 };
            AdManager.ins().showAd({
              ad_id: FuncEntryData.ins().getFuncAdId(10100701 /* home_page */, "ad"),
              ext: JSON.stringify(jsoninfo)
            });
          }
        });
      } else {
        TipsManager.ins().showInputBox({
          title: "修改名称",
          prompt: "请输入新的名称(最多6个字)",
          maxChars: 6,
          okStyle: {
            btnSrc: "ui_btn_ty_r2",
            title: `修改`,
            titleStrokeColor: "#CD4202"
          },
          boxHeight: 350,
          content: `本次修改花费${BagUtils.getThingHtmlIconPath(600010 /* CHANGE_NICK_CARD */, 48, 48)}x1`,
          restrict: "a-zA-Z,\\u4e00-\\u9fa5,0-9,*",
          callback_ok: (newName) => {
            if (StringUtils.isNullOrEmpty(newName)) {
              TipsManager.ins().showMessageTips("名称为空！");
              return false;
            }
            if (BagUtils.isEnough(600010 /* CHANGE_NICK_CARD */, 1)) {
              PlayerProtoUtils.send_set_nick_req(newName, 2);
            } else {
              const shopItem = ShopData.ins().getShopItemByItemId(600010 /* CHANGE_NICK_CARD */);
              ShopManager.ins().buyShopItem(shopItem.id);
              return false;
            }
          }
        });
      }
    }
    /**
     * 修改签名
     */
    updateSign() {
      const isFirstSetSign = !PlayerData.ins().hasSetSign;
      TipsManager.ins().showInputBox({
        title: "修改签名",
        prompt: "请输入新的签名(最多24字)",
        maxChars: 24,
        boxHeight: 365,
        okStyle: {
          btnSrc: isFirstSetSign ? "ui_btn_ty_g2" : "ui_btn_ty_r2",
          title: isFirstSetSign ? "首次免费" : `${BagUtils.getThingHtmlIconPath(1 /* DIAMOND */, 48, 48)} 2 修改`,
          titleStrokeColor: isFirstSetSign ? "#4d7b26" : "#CD4202"
        },
        restrict: "a-zA-Z,\\u4e00-\\u9fa5,0-9,*",
        content: "点击按钮确认修改",
        callback_ok: (newSign) => {
          if (StringUtils.isNullOrEmpty(newSign)) {
            TipsManager.ins().showMessageTips("签名为空！");
            return false;
          }
          if (newSign == PlayerData.ins().Sign) {
            TipsManager.ins().showMessageTips("签名没有变化");
            return false;
          }
          if (!isFirstSetSign && !BagUtils.checkEnough(1 /* DIAMOND */, 2)) {
            return false;
          }
          PlayerProtoUtils.send_set_sign_req(newSign);
          return true;
        }
      });
    }
  };

