  // src/script/module/reliefgift/view/UIReliefGiftView.ts
  var UIReliefGiftView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/reliefgift/UIReliefGiftView.lh";
    }
    onConstruct() {
      this.btn_close = this.elems.getElement("btn_close");
      this.addClickListener(this.btn_close, this.close);
      this.btn_adGet = this.elems.getElement("btn_adGet");
      if (this.btn_adGet) {
        this.addClickListener(this.btn_adGet, this.onClickAdGet);
        this.txt_ad = this.btn_adGet.getChild("txt_ad");
        if (this.txt_ad) {
          this.txt_ad.html = true;
        }
      }
      this.btn_ad = this.elems.getElement("btn_ad");
      if (this.btn_ad) {
        this.addClickListener(this.btn_ad, this.onClickAd);
      }
      this.txt_info = this.elems.getElement("txt_info");
      this.txt_coinnum = this.elems.getElement("txt_coinnum");
    }
    onOpen(...args) {
      ReliefGiftProtoUtils.player_free_coin_count_info_tos();
      this.updateView();
    }
    onRegisterEvent() {
      this.registerEvent(39 /* ReliefGiftChange */, this.updateView);
    }
    onClose() {
    }
    updateView() {
      const maxGetNum = ReliefGiftManager.ins().getMaxGetNum();
      const leftTimes = Math.max(0, maxGetNum - ReliefGiftData.ins().cnt_get);
      this.txt_info.text = "今日可领次数：" + UIUtils.getColorText(leftTimes.toString(), "D5A061") + "/" + maxGetNum;
      if (this.btn_ad) {
        this.btn_ad.getController("c1").selectedIndex = 0;
      }
      this.updateRewardAndButtonText();
    }
    onClickAdGet() {
      const isVideoSelected = this.isVideoSelected();
      if (!isVideoSelected) {
        this.onClickGet();
        return;
      }
      const adId = ReliefGiftManager.ins().getCurrentAdId();
      if (adId <= 0) {
        TipsManager.ins().showMessageTips("广告配置错误");
        return;
      }
      const jsoninfo = {
        "video_id": adId,
        "is_double": true
      };
      AdManager.ins().showAd({ ad_id: adId, ext: JSON.stringify(jsoninfo) });
    }
    onClickGet() {
      ReliefGiftProtoUtils.player_free_coin_count_get_tos();
    }
    onClickAd() {
      if (!this.btn_ad) {
        return;
      }
      this.btn_ad.getController("c1").selectedIndex = this.btn_ad.getController("c1").selectedIndex == 1 ? 0 : 1;
      this.updateRewardAndButtonText();
    }
    isVideoSelected() {
      return !!this.btn_ad && this.btn_ad.getController("c1").selectedIndex == 0;
    }
    updateRewardAndButtonText() {
      const isVideoSelected = this.isVideoSelected();
      this.txt_coinnum.text = ReliefGiftManager.ins().getRewardCoin(isVideoSelected).toString();
      if (!this.txt_ad) {
        return;
      }
      if (isVideoSelected) {
        const iconHtml = AdUtils.checkVideoIcon(ReliefGiftManager.ins().getCurrentAdId());
        this.txt_ad.text = `${iconHtml} 两倍领取`;
      } else {
        this.txt_ad.text = "领取";
      }
    }
  };

