  // src/script/layaComponent/TextWaveAnim.ts
  var TextWaveAnim = class extends Laya.Script {
    constructor() {
      super(...arguments);
      this.step = 120;
      this.up = 180;
      this.down = 180;
      this.gap = 200;
      this.scaleRate = 1.2;
      this.nodes = [];
      this.baseScales = [];
      this.running = false;
    }
    onEnable() {
      this.cacheNodes();
      this.start();
    }
    onDisable() {
      this.stop();
    }
    start() {
      if (this.running) {
        return;
      }
      if (this.nodes.length === 0) {
        this.cacheNodes();
      }
      if (this.nodes.length === 0) {
        return;
      }
      this.running = true;
      this.playWave();
      Laya.timer.loop(this.getDuration(), this, this.playWave);
    }
    stop() {
      if (!this.running) {
        this.resetNodes();
        return;
      }
      this.running = false;
      Laya.timer.clear(this, this.playWave);
      this.resetNodes();
    }
    getDuration() {
      return (this.nodes.length - 1) * this.step + this.up + this.down + this.gap;
    }
    playWave() {
      if (!this.running) {
        return;
      }
      for (let i = 0; i < this.nodes.length; i++) {
        const node = this.nodes[i];
        const base = this.baseScales[i];
        if (!node || !base) {
          continue;
        }
        Laya.Tween.killAll(node);
        node.scaleX = base.x;
        node.scaleY = base.y;
        const targetX = base.x * this.scaleRate;
        const targetY = base.y * this.scaleRate;
        Laya.Tween.to(
          node,
          { scaleX: targetX, scaleY: targetY },
          this.up,
          Laya.Ease.quadOut,
          Laya.Handler.create(this, () => {
            Laya.Tween.to(node, { scaleX: base.x, scaleY: base.y }, this.down, Laya.Ease.quadIn);
          }),
          this.step * i
        );
      }
    }
    cacheNodes() {
      this.nodes = this.getChildren(this.owner);
      this.baseScales = this.nodes.map((node) => ({ x: node.scaleX, y: node.scaleY }));
    }
    getChildren(node) {
      if (!node) {
        return [];
      }
      const children = [];
      const anyNode = node;
      if (typeof anyNode.numChildren === "number" && typeof anyNode.getChildAt === "function") {
        for (let i = 0; i < anyNode.numChildren; i++) {
          const child = anyNode.getChildAt(i);
          if (child) {
            children.push(child);
          }
        }
        return children;
      }
      if (Array.isArray(anyNode._children)) {
        for (const child of anyNode._children) {
          if (child) {
            children.push(child);
          }
        }
      }
      return children;
    }
    resetNodes() {
      for (let i = 0; i < this.nodes.length; i++) {
        const node = this.nodes[i];
        const base = this.baseScales[i];
        if (!node || !base) {
          continue;
        }
        Laya.Tween.killAll(node);
        node.scaleX = base.x;
        node.scaleY = base.y;
      }
    }
  };

