  // src/script/module/learn/LearnModule.ts
  var LearnModule = class extends BaseModule {
    onInit() {
      LearnData.ins().onReady();
      RedDotManager.ins().registerRedDot(LearnRedDot.ins());
      this.registerMessage(cmd.xq_guide_info_s2c, this.xq_guide_info_s2c);
      this.registerMessage(cmd.xq_guide_finish_s2c, this.xq_guide_finish_s2c);
      this.registerMessage(cmd.xq_chapter_gtrwds_s2c, this.xq_chapter_gtrwds_s2c);
    }
    onLogin(toc) {
      LearnProtoUtils.xq_guide_info_c2s();
    }
    onRegisterView() {
    }
    onAfterLogin(s2c) {
    }
    onCrossDay(s2c) {
    }
    onDispose() {
    }
    /**
     * 处理引导信息响应
     * @param s2c 响应数据
     */
    xq_guide_info_s2c(s2c) {
      LearnData.ins().setGuidePanelInfo(s2c);
      EventEngine.dispatchEvent(11 /* LearnChange */);
    }
    /**
     * 处理完成引导响应
     * @param s2c 响应数据
     */
    xq_guide_finish_s2c(s2c) {
      if (s2c.ret != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(s2c.ret);
        return;
      }
      LearnData.ins().updateGuideDisplayInfo(s2c.guide_id, s2c.guide_step);
      EventEngine.dispatchEvent(11 /* LearnChange */);
    }
    /**
     * 处理领取章节奖励响应
     * @param s2c 响应数据
     */
    xq_chapter_gtrwds_s2c(s2c) {
      if (s2c.ret != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(s2c.ret);
        return;
      }
      LearnData.ins().updateGtrwdsChapterIds(s2c.chapter_id);
      EventEngine.dispatchEvent(11 /* LearnChange */);
    }
  };

  // src/script/module/mail/data/MailData.ts
  var MailData = class extends BaseDataClass {
    set friendMailList(friend_mailList) {
      this.friend_mailList = friend_mailList;
    }
    get friendMailList() {
      return this.friend_mailList;
    }
    set sysMailList(sys_mailList) {
      this.sys_mailList = sys_mailList;
    }
    get sysMailList() {
      return this.sys_mailList;
    }
    /**
     * 根据type获取邮件列表
     */
    getMailListByType(type) {
      var _a, _b;
      if (type == 0) {
        return (_a = this.friend_mailList) != null ? _a : [];
      } else if (type == 1) {
        return (_b = this.sys_mailList) != null ? _b : [];
      }
      return [];
    }
    set mailInfo(value) {
      this._mailInfo = value;
    }
    get mailInfo() {
      return this._mailInfo;
    }
    /**
     * 根据type一键设置状态1未读2已读3已领取
     */
    setAllMailStatus(type, status) {
      let list = this.getMailListByType(type);
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          list[i].status = status;
        }
      }
    }
    /**
     * 根据type返回未读邮件数
     */
    getUnReadMailNum(type) {
      let list = this.getMailListByType(type);
      let num = 0;
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].status == 1) {
            num++;
          }
        }
      }
      return num;
    }
    /** 
     * 根据type返回未领取邮件数
     */
    getUnGetMailNum(type) {
      let list = this.getMailListByType(type);
      let num = 0;
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].reward) {
            if (list[i].status != 3) {
              num++;
            }
          }
        }
      }
      return num;
    }
    /**
     * 获取所有未读邮件id返回数组
     */
    getUnReadMailIdList(type) {
      let list = this.getMailListByType(type);
      let idList = [];
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].status == 1) {
            idList.push(list[i].id);
          }
        }
      }
      return idList;
    }
    /**获取所有已读且已领取邮件id数组 */
    getMailReadListByType(type) {
      let list = this.getMailListByType(type);
      let idList = [];
      list.forEach((item2) => {
        if (item2.reward) {
          if (item2.status == 3) {
            idList.push(item2.id);
          }
        } else {
          if (item2.status == 2) {
            idList.push(item2.id);
          }
        }
      });
      return idList;
    }
    /**
     * 获取所有未读且未领奖的邮件id
     */
    getMailUnreadRewardMailIdList(type) {
      let list = this.getMailListByType(type);
      let idList = [];
      list.forEach((item2) => {
        if (item2.reward) {
          if (item2.status != 3) {
            idList.push(item2.id);
          }
        } else {
          if (item2.status == 1) {
            idList.push(item2.id);
          }
        }
      });
      return idList;
    }
    /**
     * 根据id和状态码修改邮件状态
     */
    updateMailStatus(id, status) {
      let list = this.getMailListByType(0);
      let index;
      if (list.length > 0) {
        list.forEach(
          (item2) => {
            if (item2.id == id) {
              index = item2;
              item2.status = status;
            }
          }
        );
      }
      if (!index) {
        list = this.getMailListByType(1);
        if (list.length > 0) {
          list.forEach(
            (item2) => {
              if (item2.id == id) {
                item2.status = status;
              }
            }
          );
        }
      }
    }
    /**
     * 根据id和type删除邮件
     * @type 邮件类型
     */
    deleteMailById(id, type) {
      let list = this.getMailListByType(type);
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].id == id) {
            list.splice(i, 1);
          }
        }
      }
    }
    /**
     * 获取系统邮件配置表
     */
    getSysMailConfig() {
      return ConfigUtil.Tables.mail.getDataList();
    }
    /**
     * 获取语言配置的对应行表
     * @returns 对应语言配置的邮件配置
     */
    getTitleLangMailCfg(id) {
      let config = this.getSysMailConfig();
      let content = "";
      config.forEach((element) => {
        if (element.id == id) {
          content = element.title;
        }
      });
      return content;
    }
    /**
     * 获取语言配置的对应行表
     * @returns 对应语言配置的邮件配置
     */
    getContentLangMailCfg(id) {
      let config = this.getSysMailConfig();
      let content = "";
      config.forEach((element) => {
        if (element.id == id) {
          content = element.content;
        }
      });
      return content;
    }
  };

