  // src/script/module/sign/utils/SignUtils.ts
  var SignUtils = class {
    /**
     * 当前累计签到距离稀有奖励天数
     * @param day 天数
     */
    static dayOfSPReward(day) {
      let list = SignData.ins().getSPRewardDayList();
      for (let i = 0; i < list.length; i++) {
        if (list[i] - day > 0) {
          return list[i] - day;
        }
      }
      return -1;
    }
    /**
     * 获取当天是否是特殊奖励
     */
    static isSPday() {
      let list = SignData.ins().getSPRewardDayList();
      for (let i = 0; i < list.length; i++) {
        if (list[i] == SignData.ins().getDay()) {
          return true;
        }
      }
      return false;
    }
  };

  // src/script/module/sign/view/UISignView.ts
  var UISignView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      this.showCallBack = null;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/sign/UISignView.lh";
    }
    onConstruct() {
      var _a, _b;
      this.list_items = this.elems.getList("list_reward");
      this.list_items.itemCtrl = SignRewardListCtrl;
      this.btn_sign = this.elems.getElement("btn_sign");
      this.addClickListener(this.btn_sign, this.onClickSign);
      this.btn_ad = this.elems.getElement("btn_AD");
      this.addClickListener(this.btn_ad, this.onClickAD);
      this.txt_adinfo = this.elems.getElement("txt_adinfo");
      this.txt_info = this.elems.getElement("txt_info");
      this.txt_video = this.elems.getElement("txt_video", false);
      this.img_video = this.elems.getElement("img_video", false);
      if (!this.txt_video && ((_a = this.btn_sign) == null ? void 0 : _a.getChild)) {
        this.txt_video = this.btn_sign.getChild("txt_video");
      }
      if (!this.img_video && ((_b = this.btn_sign) == null ? void 0 : _b.getChild)) {
        this.img_video = this.btn_sign.getChild("img_video");
      }
      this.btn_close = this.elems.getElement("btn_close");
      this.addClickListener(this.btn_close, this.close);
    }
    onRegisterEvent() {
      this.registerEvent(19 /* SignChange */, this.updateView);
    }
    onOpen(...args) {
      this.showCallBack = args.length > 0 ? args[0] : null;
      SignData.ins().setSignAdStatus(0);
      this.updateView();
    }
    onClose() {
      if (this.showCallBack) {
        this.showCallBack(true);
        this.showCallBack = null;
      }
    }
    updateView() {
      const signData = SignData.ins();
      const signStatus = signData.getSignStatus();
      const adStatus = signData.getSignAdStatus();
      const day = signData.getDay();
      const isSignedByAd = signStatus === 2;
      const isAgainSign = signStatus === 1;
      this.btn_ad.visible = !isAgainSign;
      this.txt_adinfo.x = !isAgainSign ? 146 : 120;
      this.btn_ad.mouseEnabled = !isSignedByAd;
      UIUtils.setNodeCtrlStatus(this.btn_sign, isSignedByAd ? 1 : 0, "c1");
      this.btn_sign.enabled = !isSignedByAd;
      if (this.txt_video) {
        this.txt_video.visible = !isSignedByAd;
        this.txt_video.text = isAgainSign ? "继续签到" : "视频签到";
      }
      if (this.img_video) {
        this.img_video.visible = !isSignedByAd;
      }
      if (!this.updateInfoText(signStatus, day)) {
        TipsManager.ins().showMessageTips("出错啦，数据有误。");
      }
      if (day < 1 || day > 7) {
        return;
      }
      const reward4 = signData.getSignDataByDay();
      if (!reward4) {
        TipsManager.ins().showMessageTips("出错啦，签到奖励配置缺失。");
        return;
      }
      const sourceData = this.getSourceData(reward4, signStatus, adStatus);
      this.list_items.setUpdateParam(isSignedByAd ? 1 : 0, reward4.type);
      this.list_items.array = sourceData;
      this.btn_ad.getController("c1").selectedIndex = adStatus;
      AdUtils.checkVideoIcon(FuncEntryData.ins().getFuncAdId(102003 /* sign_in */, "ad"), this.img_video);
    }
    onClickSign() {
      if (this.btn_ad.getController("c1").selectedIndex == 1) {
        SignProtoUtils.sign_c2s();
      } else {
        AdManager.ins().showAd({
          ad_id: FuncEntryData.ins().getFuncAdId(102003 /* sign_in */, "ad")
        });
      }
    }
    onClickAD() {
      const ctrl = this.btn_ad.getController("c1");
      ctrl.selectedIndex = ctrl.selectedIndex === 1 ? 0 : 1;
      SignData.ins().setSignAdStatus(ctrl.selectedIndex);
      this.updateView();
    }
    updateInfoText(signStatus, day) {
      const signDay = signStatus === 0 ? day - 1 : day;
      const spDay = SignUtils.dayOfSPReward(signDay);
      if (spDay === -1) {
        return false;
      }
      const color = "449F20";
      const signedText = UIUtils.getColorText(signDay.toString(), color);
      const rareText = UIUtils.getColorText("稀有奖励", color);
      if (SignUtils.isSPday()) {
        this.txt_info.text = "今天是" + rareText + "，已签到" + signedText + "天";
        return true;
      }
      this.txt_info.text = UIUtils.getColorText(spDay.toString(), color) + "天后出现" + rareText + "，已签到" + signedText + "天";
      return true;
    }
    getSourceData(reward4, signStatus, adStatus) {
      if (signStatus === 1) {
        return reward4.reward_again;
      }
      return adStatus === 0 ? reward4.reward_onAd : reward4.reward;
    }
  };

