  // src/script/module/daytask/utils/DayTaskUtils.ts
  var DayTaskUtils = class _DayTaskUtils {
    /**
     * 判断是否有可完成或可以领取奖励的任务
     * @returns true: 有可完成或可领取奖励的任务, false: 没有
     */
    static hasCompletableOrRewardableTasks() {
      const taskData = TaskData.ins();
      return taskData.getTasksByStatus(2).size > 0;
    }
    /**
     * 获取可领取奖励的任务ID列表
     * @returns 可领取奖励的任务ID数组
     */
    static getRewardTaskIds() {
      const taskData = TaskData.ins();
      return taskData.getCompletedButUnclaimedTaskIds();
    }
    /**
     * 判断奖励是否已领取
     * @param rewardData 奖励数据
     * @returns boolean
     */
    static isRewardGot(rewardData) {
      return rewardData.status === 3;
    }
    /**
     * 判断是否达到活跃值目标
     * @param cur 当前活跃值
     * @param target 目标活跃值
     */
    static isReachActive(cur, target) {
      return cur >= target;
    }
    /**
     * 判断奖励是否可领取
     * @param curActive 当前活跃值
     * @param targetActive 目标活跃值
     * @param rewardData 奖励数据
     * @returns boolean
     */
    static canGetReward(curActive, targetActive, rewardData) {
      return !this.isRewardGot(rewardData) && curActive >= targetActive;
    }
    /**
     * 判断某个活跃度奖励id是否已领取
     * @param rewardId 奖励id
     * @returns boolean
     */
    static isProRewardGot(rewardId) {
      var _a;
      const rewards = ((_a = DayTaskData.ins().data) == null ? void 0 : _a.rewards) || [];
      const isGot = rewards.includes(rewardId);
      return isGot;
    }
    /**
     * 获取任务状态的优先级
     * @param status 任务状态
     * @returns 优先级数值
     */
    static getStatusPriority(status) {
      if (status === 2)
        return 0;
      if (status === 0 || status === 1)
        return 1;
      if (status === 3)
        return 2;
      return 3;
    }
    /**
     * 任务排序方法
     * 1. 先按状态优先级排序（可领取 > 未完成 > 已完成）
     * 2. 同状态下按 sort 字段从小到大排序
     */
    static sortTaskList(list) {
      return list.sort((a, b) => {
        const pa = _DayTaskUtils.getStatusPriority(a.status);
        const pb = _DayTaskUtils.getStatusPriority(b.status);
        if (pa !== pb) {
          return pa - pb;
        }
        return (a.sort || 0) - (b.sort || 0);
      });
    }
  };

  // src/script/module/daytask/DayTaskRedDot.ts
  var DayTaskRedDot = class extends RedDotBase {
    constructor() {
      super(104001 /* task */);
      this.setConnectedEvents(21 /* TaskChange */, 22 /* DayTaskChange */);
    }
    doCheck() {
      var _a;
      const taskData = TaskData.ins();
      const serverDailyTaskIds = ((_a = DayTaskData.ins().data) == null ? void 0 : _a.tasks) || [];
      for (const taskId of serverDailyTaskIds) {
        const taskStatus = taskData.getTaskStatus(taskId);
        if (taskStatus === 2) {
          return 1;
        }
      }
      const dayRewards = DayTaskData.ins().getDayProgressByTypeId(1);
      const curDayActive = DayTaskData.ins().getDailyActive();
      for (const reward4 of dayRewards) {
        const isGot = DayTaskUtils.isProRewardGot(reward4.id);
        if (!isGot && curDayActive >= reward4.point) {
          return 1;
        }
      }
      const weekRewards = DayTaskData.ins().getDayProgressByTypeId(2);
      const curWeekActive = DayTaskData.ins().getWeekActive();
      for (const reward4 of weekRewards) {
        const isGot = DayTaskUtils.isProRewardGot(reward4.id);
        if (!isGot && curWeekActive >= reward4.point) {
          return 1;
        }
      }
      return 0;
    }
  };

