  // src/script/module/activity/data/ActivityData.ts
  var ActivityData = class _ActivityData extends BaseDataClass {
    constructor() {
      super(...arguments);
      /**
       * 后台缓存的活动中心数据
       */
      this.act_center = null;
    }
    /**
     * 通过活动入口列表
     */
    getActEntryList() {
      return ConfigUtil.Tables.activity_id.getDataList();
    }
    /**
     * 获取当前激活的活动入口列表
     * @param type 类型
     */
    getActiveEntryListByType(type) {
      let showActList = [];
      const now = TimeData.ins().serverTimeS;
      const actList = _ActivityData.ins().getActEntryList();
      for (const act of actList) {
        if (act.type_title != type) {
          continue;
        }
        if (act.mode_show == 0 /* Image */ || act.mode_show == 5 /* Notice */) {
          if (now < act.time_up || now > act.time_down) {
            continue;
          }
          showActList.push(act);
        }
      }
      if (this.act_center) {
        for (let act of this.act_center.list) {
          const cfg = ConfigUtil.Tables.activity_id.get(act.id);
          if (!cfg || cfg.type_title != type) {
            continue;
          }
          showActList.push(cfg);
        }
      }
      showActList.sort((a, b) => {
        if (a.order != b.order) {
          return a.order - b.order;
        }
        return a.id - b.id;
      });
      return showActList;
    }
    /**
     * 获取活动配置最后的检查时间
     * 用于红点判断
     * @param cfg 配置
     */
    getLastCheckTime(cfg) {
      return parseInt(PlayerLocalStorageManager.ins().getString("activity", `act_check_${cfg.id}`)) || 0;
    }
    /**
     * 保存活动配置最后的检查时间
     * 使用当前时间
     * @param cfg 配置
     */
    saveLastCheckTime(cfg) {
      PlayerLocalStorageManager.ins().saveString("activity", `act_check_${cfg.id}`, TimeData.ins().serverTimeS.toString());
    }
    /**
     * 获取任务模板1类型的任务列表
     */
    getActTaskType1List(mode_id) {
      const cfg = ConfigUtil.Tables.mode_type1.get(mode_id);
      if (!cfg) {
        return [];
      }
      return cfg.taskgroup;
    }
  };

