  // src/script/module/activity/ActivityRedDot.ts
  var ActivityRedDot = class extends RedDotBase {
    constructor() {
      super(103005 /* activity */);
      this._actRedDotEveryMap = {};
      this._actRedDots = {};
      /**
       * 活动页签红点数量
       */
      this.activityRedNum = 0;
      /**
       * 公告页签红点数量
       */
      this.noticeRedNum = 0;
      this.setConnectedEvents(23 /* ActivityChange */, 21 /* TaskChange */);
    }
    doCheck() {
      this.activityRedNum = 0;
      this.noticeRedNum = 0;
      {
        const list = ActivityData.ins().getActiveEntryListByType(0 /* Activity */);
        for (let item2 of list) {
          const hasRed = this.checkCfgRedStatus(item2);
          if (hasRed) {
            this.activityRedNum++;
          }
        }
      }
      {
        const list = ActivityData.ins().getActiveEntryListByType(1 /* Notice */);
        for (let item2 of list) {
          const hasRed = this.checkCfgRedStatus(item2);
          if (hasRed) {
            this.noticeRedNum++;
          }
        }
      }
      return this.activityRedNum + this.noticeRedNum;
    }
    /**
     * 检查某个条目的红点状态
     * @param item 
     * @returns 
     */
    checkCfgRedStatus(item2) {
      let result = false;
      switch (item2.point_red) {
        case 1 /* Daily */: {
          const lastTime = ActivityData.ins().getLastCheckTime(item2);
          if (!TimeUtils.isSameDay(lastTime, TimeData.ins().serverTimeS)) {
            result = true;
          }
          break;
        }
        case 3 /* LifeOnce */: {
          const lastTime = ActivityData.ins().getLastCheckTime(item2);
          if (lastTime == 0) {
            result = true;
          }
          break;
        }
        case 2 /* Every */: {
          if (!this._actRedDotEveryMap[item2.id]) {
            result = true;
          }
          break;
        }
      }
      if (item2.mode_show == 1 /* TaskSingle1 */) {
        const taskList = ActivityData.ins().getActTaskType1List(item2.mode_id);
        for (const taskId of taskList) {
          if (TaskData.ins().getTaskStatus(taskId) == 2) {
            result = true;
            break;
          }
        }
      }
      this._actRedDots[item2.id] = result;
      return result;
    }
    /**
     * 移除红点标记
     * @param item 配置
     */
    removeCfgRedStatus(item2) {
      if (this._actRedDots[item2.id]) {
        this._actRedDots[item2.id] = false;
        if (item2.point_red != 2 /* Every */) {
          ActivityData.ins().saveLastCheckTime(item2);
        } else {
          this._actRedDotEveryMap[item2.id] = true;
        }
        EventEngine.dispatchEvent(23 /* ActivityChange */);
      }
    }
  };

