  // src/script/module/club/ClubPageManager.ts
  var ClubPageManager = class _ClubPageManager extends BaseClass {
    constructor() {
      super(...arguments);
      /**
       * 俱乐部列表分页
       */
      this.clubPage = new PageList();
      /**
       * 俱乐部列表（符合条件）分页
       */
      this.clubRecomPage = new PageList();
      /**
       * 俱乐部列表（符合条件）分页
       */
      this.clubMemberPage = new PageList();
      /**
       * 符合条件的分页偏移
       */
      this.recomOffset = 0;
      /**
       * 俱乐部搜索列表
       */
      this.searchList = [];
    }
    /**
     * 建立page关系
     */
    buildPages() {
      this.clubPage.bindNextPageCall(this, this.onClubNextPageStart, this.onClubNextPageEnd);
      this.clubRecomPage.bindNextPageCall(this, this.onClubRecomNextPageStart, this.onClubRecomNextPageEnd);
      this.clubMemberPage.bindNextPageCall(this, this.onClubMemberNextPageStart, this.onClubMemberNextPageEnd);
    }
    /**
     * 修改本地缓存的俱乐部申请状态
     * @param clubid 俱乐部id
     * @param apply 申请状态
     */
    setClubApplyStatus(clubid, apply) {
      let localCache = _ClubPageManager.ins().clubPage.array.find((element) => {
        return element.clubid == clubid;
      });
      if (localCache) {
        localCache.is_apply = apply;
      }
      localCache = _ClubPageManager.ins().clubRecomPage.array.find((element) => {
        return element.clubid == clubid;
      });
      if (localCache) {
        localCache.is_apply = apply;
      }
      localCache = this.searchList.find((element) => {
        return element.clubid == clubid;
      });
      if (localCache) {
        localCache.is_apply = apply;
      }
    }
    /**
     * 俱乐部列表翻页回调
     * @param page 页数
     */
    onClubNextPageStart(page) {
      ClubProtoUtils.club_rank_get_tos(page);
    }
    /**
     * 收到俱乐部列表分页数据
     * @param page 页数
     * @param dataList 数据信息
     */
    onClubNextPageEnd(page, dataList) {
    }
    /**
     * 俱乐部列表翻页回调
     * @param page 页数
     */
    onClubRecomNextPageStart(page) {
      ClubProtoUtils.club_lvl_recom_get_tos(page, page == this.recomOffset);
    }
    /**
     * 收到俱乐部列表分页数据
     * @param page 页数
     * @param dataList 数据信息
     */
    onClubRecomNextPageEnd(page, dataList) {
    }
    /**
     * 俱乐部成员列表翻页回调
     * @param page 页数
     */
    onClubMemberNextPageStart(page) {
      ClubProtoUtils.club_get_user_list_tos(page);
    }
    /**
     * 收到俱乐部成员列表分页数据
     * @param page 页数
     * @param dataList 数据信息
     */
    onClubMemberNextPageEnd(page, dataList) {
    }
  };

