  // src/script/module/chat/chatPanel/ctrls/ChatRoomInviteCtrl.ts
  var ChatRoomInviteCtrl = class extends ChatCtrlBase {
    constructor() {
      super(...arguments);
      this._cfgId = 0;
      this._roomId = 0;
      // 能否进入房间
      this._canEnterRoom = false;
    }
    onConstruct() {
      this.txt_name = ElemFinder.getElement(this.rootNode, "txt_name");
      this.txt_link = ElemFinder.getElement(this.rootNode, "txt_link");
      UIUtils.addClickListener(this.rootNode, this, this.onClick);
    }
    onDestroy() {
      this._roomId = 0;
      this._cfgId = 0;
    }
    onUpdate(msg) {
      if (msg.extra_param && msg.extra_param.length >= 2) {
        this._roomId = parseInt(msg.extra_param[0]);
        this._cfgId = parseInt(msg.extra_param[1]);
        const ruleCfg = FriendRoomData.ins().getFriendRoomCfg(this._cfgId);
        if (ruleCfg) {
          this.txt_name.text = `我刚刚创建了【${ruleCfg.rule_name}】房间，一起来玩吧`;
          if (this._roomId) {
            const roomInfo = GameRoomManager.ins().getRoomCountInfo(this._roomId);
            if (!roomInfo) {
              GameRoomManager.ins().requestRoomCountInfo(this._roomId);
            }
          }
        } else {
          this.txt_name.text = "";
        }
      } else {
        this.txt_name.text = "";
      }
      this.updateRoomInfo();
    }
    updateRoomInfo() {
      const roomInfo = GameRoomManager.ins().getRoomCountInfo(this._roomId);
      if (roomInfo) {
        if (roomInfo.count === 1 || roomInfo.count === 2 && roomInfo.inroom) {
          this._canEnterRoom = true;
          this.txt_link.text = "进入房间";
          this.txt_link.color = "#ffffff";
          this.txt_link.underline = true;
        } else {
          this._canEnterRoom = false;
          this.txt_link.text = "房间已开始或已解散";
          this.txt_link.color = "#AAB5D2";
          this.txt_link.underline = false;
        }
      } else {
        this._canEnterRoom = false;
        this.txt_link.text = "";
      }
    }
    onClick() {
      if (this._canEnterRoom) {
        GameRoomManager.ins().tryEnterRoom(this._roomId, this.msg.fromnick);
      } else {
        TipsManager.ins().showMessageTips(`房间已开始或已解散`);
      }
    }
  };

