  // src/script/module/chat/chatPanel/ctrls/ChatSystemTextCtrl.ts
  var ChatSystemTextCtrl = class extends ChatCtrlBase {
    onConstruct() {
      this.txt_content = ElemFinder.getElement(this.rootNode, "txt_content");
    }
    onUpdate(msg) {
      this.rootNode.x = this.panelWidth / 2;
      if (StringUtils.isNullOrEmpty(msg.context)) {
        let cfgId = parseInt(msg.extra_param[0]);
        let config = ClubData.ins().getClubNews(cfgId);
        let str = (config == null ? void 0 : config.news_name) || "";
        let linkJson = [];
        for (let i = 1; i < msg.extra_param.length; i++) {
          try {
            let linkParam = JSON.parse(msg.extra_param[i]);
            linkJson.push({
              type: Number(linkParam.type),
              val: String(linkParam.val)
            });
          } catch (error) {
            console.error(error);
          }
        }
        let linkStr = LinkUtils.getLink(str, linkJson);
        this.txt_content.color = "#DBBF8E";
        this.txt_content.text = linkStr;
      } else {
        this.txt_content.text = msg.context;
        this.txt_content.color = "#DBBF8E";
      }
      this.rootNode.height = this.txt_content.textHeight + 45;
    }
  };

