  // src/script/module/chat/view/UIChatSpeakerView.ts
  var UIChatSpeakerView = class extends UITabSubView {
    get path() {
      return "ui/prefab/module/chat/UIChatSpeakerView.lh";
    }
    get layer() {
      return 2 /* Second */;
    }
    onConstruct() {
      this.btn_x = this.elems.getElement("btn_x");
      this.input = this.elems.getElement("input");
      this.input.maxChars = ChatConst.MAX_SPEAKER_INPUT_LEN;
      this.input.textIns.on(Laya.Event.INPUT, this, this.onInputCheck);
      this.btn_ok = this.elems.getUIButton("btn_ok");
      this.txt_material = this.elems.getElement("txt_material");
      this.txt_input_size = this.elems.getElement("txt_input_size");
      this.addClickListener(this.btn_ok.rootNode, this.onClickOk);
      this.addClickListener(this.btn_x, this.close);
    }
    onRegisterEvent() {
      this.registerEvent(1 /* ThingChange */, this.updateView);
    }
    onOpen(...args) {
      this.input.text = "";
      this.onInputCheck();
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const matNum = CurrencyData.ins().getCurrency(9 /* LOUDSPEAKER */);
      this.txt_material.text = `当前剩余喇叭：${matNum}`;
    }
    onRedDotChange() {
    }
    /**
     * 检查输入长度超出限制
     * @param data 
     */
    onInputCheck() {
      if (this.input.text.length >= ChatConst.MAX_SPEAKER_INPUT_LEN) {
        TipsManager.ins().showMessageTips(StringUtils.format(ChatConst.INPUT_LIMIT_TIP, ChatConst.MAX_SPEAKER_INPUT_LEN));
      }
      this.txt_input_size.text = `您还可以输入${this.input.maxChars - this.input.text.length}个字`;
    }
    /**
     * 点击确认
     */
    onClickOk() {
      const worldLimitLevel = ChatUtils.getWorldChatLimitLevel();
      if (PlayerData.ins().level < worldLimitLevel) {
        TipsManager.ins().showMessageTips(`${worldLimitLevel}级后可以发送世界消息，请先去升级吧！`);
        return;
      }
      let content = this.input.text.trim();
      if (content.length == 0) {
        TipsManager.ins().showMessageTips(ChatConst.INPUT_EMPTY_TIP);
        return;
      }
      const num = CurrencyData.ins().getCurrency(9 /* LOUDSPEAKER */);
      if (num > 0) {
        ChatProtoUtils.chat_send_msg_tos(cmd.CHAT_TO_TYPE.CTT_WORLD, content, cmd.CHAT_TYPE.LOUDSPEAKER);
        this.close();
      } else {
        ShopManager.ins().buyItem(9 /* LOUDSPEAKER */);
      }
    }
  };

