  // src/script/module/chat/ChatRedDot.ts
  var ChatRedDot = class extends RedDotBase {
    constructor() {
      super(106002 /* chat */);
      /**
       * 私聊红点数量
       */
      this.privateNewMessageNum = 0;
      /**
       * 陌生人红点数量
       */
      this.strangerNewMessageNum = 0;
      this.setConnectedEvents(4 /* ChatChange */, 24 /* ClubChange */);
    }
    doCheck() {
      this.privateNewMessageNum = 0;
      this.strangerNewMessageNum = 0;
      if (ClubData.ins().clubId > 0) {
        this.privateNewMessageNum += ChatData.ins().clubNewMessageNum;
      }
      const contactList = ChatData.ins().contactList;
      for (const userid of contactList) {
        this.privateNewMessageNum += ChatData.ins().getNewMessageNum(userid);
      }
      const strangerContactList = ChatData.ins().strangerContactList;
      for (const userid of strangerContactList) {
        this.strangerNewMessageNum += ChatData.ins().getNewMessageNum(userid);
      }
      return this.privateNewMessageNum + this.strangerNewMessageNum;
    }
  };

