      this.img_quarter.src = this.tier == 1 /* SUPER */ ? UIUtils.getImageUrl("subscribe", "ui_icon_xq_jkdb") : UIUtils.getImageUrl("subscribe", "ui_icon_xq_xjkdb");
      this.img_year.src = this.tier == 1 /* SUPER */ ? UIUtils.getImageUrl("subscribe", "ui_icon_xq_nkdb") : UIUtils.getImageUrl("subscribe", "ui_icon_xq_xnkdb");
      this.img_icon1.src = SubscribeUtils.getMedalImage(this.tier, this.options[0].id);
      this.img_icon2.src = SubscribeUtils.getMedalImage(this.tier, this.options[1].id);
