    onRegisterView() {
      UIManager.ins().registerForm(101006 /* clubshop */, UIClubShopView);
    }
    onLogin(toc) {
      ClubData.ins().setClubId(toc.clubid);
      ClubData.ins().setClubMemberType(toc.club_jur_lvl);
      if (toc.clubid != 0) {
        if (toc.club_jur_lvl == 0) {
          console.error("club pos error: " + toc.club_jur_lvl);
        }
        ClubProtoUtils.club_get_my_club_info_tos();
        ClubProtoUtils.club_get_club_task_info_tos();
        if (ClubData.ins().clubMemberConfig.change_limit == 1) {
          ClubProtoUtils.club_admin_get_applylist_tos();
        }
      }
    }
    onAfterLogin(s2c) {
    }
    onCrossDay(s2c) {
    }
    /**
     * 创建俱乐部协议
     * @param toc 
     */
    club_create_club_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      ClubData.ins().setClubId(toc.clubid);
      ClubData.ins().setClubMemberType(1 /* Minister */);
      UIManager.ins().closeForm(UIClubCreateView);
      TipsManager.ins().showMessageTips("创建俱乐部成功");
      ClubProtoUtils.club_get_my_club_info_tos();
      ClubProtoUtils.club_get_club_task_info_tos();
    }
    /**
     * 俱乐部列表分页数据
     * @param toc 
     */
    club_rank_get_toc(toc) {
      ClubPageManager.ins().clubPage.onNextPage(toc.page, toc.infos, toc.over);
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 俱乐部列表分页数据
     * @param toc 
     */
    club_lvl_recom_get_toc(toc) {
      const over = toc.page >= ClubPageManager.ins().recomOffset + 100;
      ClubPageManager.ins().clubRecomPage.onNextPage(toc.page, toc.infos, over);
      if (over && ClubPageManager.ins().clubRecomPage.array.length == 0) {
        TipsManager.ins().showMessageTips("暂无符合条件的俱乐部");
      }
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 得到自身所在俱乐部信息反馈
     * @param toc 
     */
    club_get_my_club_info_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      ClubData.ins().clubInfo = toc;
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 俱乐部搜索
     * @param toc 
     */
    club_search_toc(toc) {
      var _a;
      let list = toc.list;
      if (list.length > 0) {
        const searchList = [];
        for (let i = 0; i < list.length; i++) {
          if (list[i].exist) {
            searchList.push(list[i].info);
          }
        }
        (_a = UIManager.ins().getForm(UIClubAddView)) == null ? void 0 : _a.showSearchResult(searchList);
      } else {
        TipsManager.ins().showMessageTips("搜索的俱乐部不存在");
      }
    }
    /**
     * 加入俱乐部申请反馈
     * @param toc 
     * @returns 
     */
    club_join_club_apply_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      TipsManager.ins().showMessageTips("申请加入俱乐部成功");
      ClubPageManager.ins().setClubApplyStatus(toc.clubid, true);
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 取消加入俱乐部申请反馈
     * @param toc 
     */
    club_join_club_cancel_apply_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      TipsManager.ins().showMessageTips("取消申请加入俱乐部成功");
      ClubPageManager.ins().setClubApplyStatus(toc.clubid, false);
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 返回申请结果
     * @param toc 
     */
    club_push_result_to_applicant_toc(toc) {
      ClubData.ins().setClubId(toc.clubid);
      if (toc.clubid != 0) {
        TipsManager.ins().showMessageTips("加入俱乐部成功");
        ClubData.ins().setClubMemberType(4 /* Normal */);
        ClubProtoUtils.club_get_my_club_info_tos();
        ClubProtoUtils.club_get_club_task_info_tos();
      }
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
