    /**
     * 退出俱乐部
     * @param toc 
     * @returns 
     */
    club_quit_club_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      ClubData.ins().setClubId(0);
      MailProtoUtils.player_new_mail_info_req_tos();
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 被踢出通知
     * @param toc 
     */
    club_push_be_kicked_toc(toc) {
      if (toc.userid == PlayerData.ins().playerId) {
        TipsManager.ins().showMessageBox({
          title: "温馨提示",
          content: "你已被" + toc.operator_name + "移除俱乐部",
          callback_ok: () => {
            ClubProtoUtils.club_quit_club_tos();
          },
          visible_cancel: false
        });
        ClubData.ins().setClubId(0);
        EventEngine.dispatchEvent(24 /* ClubChange */);
      }
    }
    /**
     * 设置权限返回
     * @param toc 
     * @returns 
     */
    club_set_position_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      ClubData.ins().vice_minister_count = toc.vice_minister_count;
      ClubPageManager.ins().clubMemberPage.refreshPages();
      if (toc.position == 1) {
        ClubData.ins().setClubMemberType(4 /* Normal */);
      }
      EventEngine.dispatchEvent(24 /* ClubChange */);
    }
    /**
     * 玩家职位发生变化时后台主动推送
     * @param toc 
     */
    club_push_set_position_toc(toc) {
      if (toc.userid == PlayerData.ins().playerId) {
        ClubData.ins().positionInfo = toc;
        ClubData.ins().setClubMemberType(toc.position);
        if (ClubData.ins().clubMemberConfig.change_limit == 1) {
          ClubProtoUtils.club_admin_get_applylist_tos();
        }
        const clubView = UIManager.ins().getForm(UIClubMainView);
        if (clubView) {
          ClubPageManager.ins().clubMemberPage.refreshPages();
        }
        EventEngine.dispatchEvent(24 /* ClubChange */);
      }
    }
