  // src/script/module/mooncard/data/MoonCardData.ts
  var MoonCardData = class extends BaseDataClass {
    constructor() {
      super(...arguments);
      /**
       * 用户月卡信息
       */
      this._userMoonCard = [];
    }
    /**
     * 获取月卡列表
     */
    getMoonCardList() {
      return ConfigUtil.Tables.month_card.getDataList();
    }
    /**
     * 获取月卡特权列表
     * @param id 
     */
    getMoonCardPrivilegeList(id) {
      let list = ConfigUtil.Tables.month_card.get(id);
      let privilege = [];
      list.privilege.forEach((element) => {
        let item2 = ConfigUtil.Tables.subscribe_new.get(element);
        privilege.push(item2.detail2);
      });
      return privilege;
    }
    /**
     * 设置月卡数据
     */
    setMoonCardData(data) {
      this._userMoonCard = data || [];
    }
    /**
     * 设置领取时间
     */
    setMoonCardGetTime(id, time) {
      let list = this._userMoonCard;
      list.forEach((element) => {
        if (element.card_id == id) {
          element.reward_time = time;
        }
      });
    }
    /**
     * 获取月卡数据
     */
    getMoonCardData() {
      return this._userMoonCard;
    }
  };

  // src/script/module/mooncard/utils/MoonCardUtils.ts
  var MoonCardUtils = class {
    /**
     * 判断月卡是否开通
     * @param id 月卡id
     * @returns 
     */
    static isHasMoonCard(id) {
      let data = MoonCardData.ins().getMoonCardData().find((item2) => item2.card_id == id);
      if (data) {
        return data.end_time > TimeData.ins().serverTimeS;
      }
      return false;
    }
    /**
     * 判断奖励是否领取
     * @param id 月卡id
     * @returns 
     */
    static isHasReward(id = -1) {
      if (id == -1) {
        for (let i = 0; i < MoonCardData.ins().getMoonCardData().length; i++) {
          let item2 = MoonCardData.ins().getMoonCardData()[i];
          if (item2.reward_time != 0 && item2.reward_time < TimeData.ins().serverTimeS) {
            return true;
          }
        }
      }
      let data = MoonCardData.ins().getMoonCardData().find((item2) => item2.card_id == id);
      if (data) {
        return data.reward_time >= TimeData.ins().serverTimeS;
      }
      return false;
    }
    /**
     * 获取剩余时间
     */
    static getMoonCardLeftTime(id) {
      let data = MoonCardData.ins().getMoonCardData().find((item2) => item2.card_id == id);
      if (data) {
        return data.end_time - TimeData.ins().serverTimeS;
      }
      return 0;
    }
  };

  // src/script/module/mooncard/MoonCardRedDots.ts
  var MoonCardRedDots = class extends RedDotBase {
    constructor() {
      super(103002 /* monthcard */);
      this.isHasReward = false;
      this.setConnectedEvents(25 /* MoonCardChange */);
    }
    doCheck() {
      this.isHasReward = MoonCardUtils.isHasReward();
      if (this.isHasReward) {
        return 1;
      } else {
        return 0;
      }
    }
  };

  // src/script/module/mooncard/MoonCardModule.ts
  var MoonCardModule = class extends BaseModule {
    onInit() {
      RedDotManager.ins().registerRedDot(MoonCardRedDots.ins());
      this.registerMessage(cmd.player_charge_time_card_s2c, this.player_charge_time_card_s2c);
      this.registerMessage(cmd.player_get_time_card_reward_s2c, this.player_get_time_card_reward_s2c);
    }
    onRegisterView() {
    }
    onLogin(toc) {
    }
    onAfterLogin(s2c) {
      if (!s2c.time_card)
        return;
      MoonCardData.ins().setMoonCardData(s2c.time_card.list);
      EventEngine.dispatchEvent(25 /* MoonCardChange */);
    }
    onCrossDay(s2c) {
    }
    player_charge_time_card_s2c(toc) {
      MoonCardData.ins().setMoonCardData(toc.info.list);
      EventEngine.dispatchEvent(25 /* MoonCardChange */);
    }
    player_get_time_card_reward_s2c(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      const now = /* @__PURE__ */ new Date();
      const nextDayZero = new Date(now);
      nextDayZero.setDate(now.getDate() + 1);
      nextDayZero.setHours(0, 0, 0, 0);
      const timestamp = Math.floor(nextDayZero.getTime() / 1e3);
      MoonCardData.ins().setMoonCardGetTime(toc.card_id, timestamp);
      EventEngine.dispatchEvent(25 /* MoonCardChange */);
    }
  };

  // src/script/module/subscribe/SubscribeRedDot.ts
  var SubscribeRedDot = class extends RedDotBase {
    constructor() {
      super(106001 /* subscribe */);
      this.setConnectedEvents(7 /* SubscribeChange */);
    }
    doCheck() {
      const hasReward = SubscribeData.ins().isSubscribed && !SubscribeData.ins().isDailyRewardGot();
      return hasReward ? 1 : 0;
    }
  };

  // src/script/module/subscribe/SubscribeEntryCtrl.ts
  var SubscribeEntryCtrl = class extends BaseFuncEntryCtrl {
    constructor() {
      super(106001 /* subscribe */);
      this.setConnectedRedDots(
        SubscribeRedDot.ins()
      );
    }
  };

  // src/script/module/subscribe/SubscribeModule.ts
  var SubscribeModule = class extends BaseModule {
    onInit() {
      RedDotManager.ins().registerRedDot(SubscribeRedDot.ins());
      FuncEntryManager.ins().registerEntryCtrl(SubscribeEntryCtrl);
      this.registerMessage(cmd.player_monthcard_info_s2c, this.player_monthcard_info_s2c);
      this.registerMessage(cmd.player_monthcard_gtrwds_s2c, this.player_monthcard_gtrwds_s2c);
      this.registerMessage(cmd.player_monthcard_lvlup_s2c, this.player_monthcard_lvlup_s2c);
    }
    onRegisterView() {
      UIManager.ins().registerForm(106001 /* subscribe */, UIMemberView);
    }
    onLogin(toc) {
      SubscribeData.ins().onReady();
      SubscribeData.ins().setSubscribe(toc.is_subscribe);
      console.log("toc.is_subscribe", toc.is_subscribe);
      console.log("toc.is_super_vip", toc.is_super_vip);
      SubscribeData.ins().setIsSuperVip(toc.is_super_vip);
      SubscribeProtoUtils.player_monthcard_info_c2s();
    }
    onAfterLogin(s2c) {
      SubscribeProtoUtils.player_monthcard_info_c2s();
    }
    onCrossDay(s2c) {
      SubscribeProtoUtils.player_monthcard_info_c2s();
    }
    refreshData(data) {
      if (!data) {
        return;
      }
      SubscribeData.ins().subscribeInfo = data;
      SubscribeData.ins().setSubscribe(data.vip_expire_tm > TimeData.ins().serverTimeS);
      SubscribeData.ins().setIsSuperVip(data.is_super_vip);
      EventEngine.dispatchEvent(7 /* SubscribeChange */);
    }
    /**
     * 获取月卡信息
     * @param s2c 
     */
    player_monthcard_info_s2c(s2c) {
      this.refreshData(s2c);
    }
    /**
     * 会员每日奖励领取
     * @param s2c 
     */
    player_monthcard_gtrwds_s2c(s2c) {
      if (s2c.result !== cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(s2c.result);
        return;
      }
      if (SubscribeData.ins().subscribeInfo) {
        SubscribeData.ins().subscribeInfo.td_gtrwd = true;
      }
      EventEngine.dispatchEvent(7 /* SubscribeChange */);
    }
    /**
     * 高级会员升级为超级会员
     * @param s2c 
     */
    player_monthcard_lvlup_s2c(s2c) {
      if (s2c.result !== cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(s2c.result);
        return;
      }
      EventEngine.dispatchEvent(7 /* SubscribeChange */);
    }
  };

