  // src/script/module/luckyWheel/utils/LuckyWheelConfigUtils.ts
  var LuckyWheelConfigUtils = class {
    static getSortedSlots() {
      const list = ConfigUtil.Tables.xyzp.getDataList().slice();
      list.sort((a, b) => a.id - b.id);
      return list;
    }
    /** 第 slotIndex（0~7）格对应的配置行 id，用于与 draw_ids / 中奖 id 对齐 */
    static getSlotIdByIndex(slotIndex) {
      const all = this.getSortedSlots();
      const row = all[slotIndex];
      if (row) {
        return row.id;
      }
      return slotIndex + 1;
    }
    /**
     * 服务端中奖格 id → 预制体 `LuckyWheelItemGrid_*` 下标（0~7）。
     * 约定：id 为 **1~8** 时表示转盘第几格（第 1 格 = 下标 0），与配置表主键 id 无关，避免表中 id=2 排在首位时误指到第 1 格。
     * 其它 id 再按 `turntable_lucky` 行 id 查找下标。
     */
    static getIndexBySlotId(slotId) {
      if (slotId >= 1 && slotId <= 8) {
        return slotId - 1;
      }
      const all = this.getSortedSlots();
      const idx = all.findIndex((c) => c.id === slotId);
      if (idx >= 0) {
        return idx;
      }
      return 0;
    }
    /**
     * 单格奖励展示：支持「8 行配置」或「1 行 + free_lucky 八段」两种导表形态
     */
    static getDisplayForSlotIndex(slotIndex) {
      const all = this.getSortedSlots();
      const row = all[slotIndex];
      if (!row || !row.reward1 || row.reward1.length == 0) {
        return { id: 0, num: 0 };
      }
      return row.reward1[0];
    }
  };

