      this.img_jd_bg_first = ElemFinder.getImage(rootNode, "img_jd_bg_first");
      this.img_jd_bg = ElemFinder.getImage(rootNode, "img_jd_bg");
      this.img_jd_first = ElemFinder.getImage(rootNode, "img_jd_first");
      this.img_jd = ElemFinder.getImage(rootNode, "img_jd");
      this.img_normal = ElemFinder.getImage(rootNode, "img_normal");
      this.img_finish = ElemFinder.getImage(rootNode, "img_finish");
