  var AwardTipsQueue = class extends BaseClass {
    constructor() {
      super(...arguments);
      this.awards_list = [];
      /**
       * 需要展示的特殊列表
       */
      this._showSpList = [];
      /**
       * 最终需要展示的道具列表
       */
      this._showAwards = [];
      /**
       * 已经使用特殊弹窗展示过的物品
       */
      this._specialAwardIds = [];
    }
    addAwards(awards, type) {
      this._type = type;
      this.awards_list.push(awards);
      this.processNext();
    }
    clearAwards() {
      this.awards_list = [];
    }
    processNext() {
      if (this._isShowing) {
        return;
      }
      if (this.awards_list.length == 0) {
        return;
      }
      this._isShowing = true;
      this._showSpList.length = 0;
      this._specialAwardIds.length = 0;
      this._showAwards = this.awards_list.splice(0, 1)[0];
      for (const award of this._showAwards) {
        const thingCfg = BagData.ins().getThingConfig(award.id);
        if (!thingCfg) {
          continue;
        }
        switch (thingCfg.maintype) {
          case 2 /* clothes */:
            this._showSpList.push({
              id: award.id,
              viewclass: UISpecialAwardTipsView
            });
            this._specialAwardIds.push(award.id);
            break;
        }
      }
      this.processSpList();
    }
    processSpList() {
      if (this._showSpList.length == 0) {
        this.processFinal();
        return;
      }
      const sp = this._showSpList.splice(0, 1)[0];
      UIManager.ins().openForm(sp.viewclass, sp.id).setCloseCallback(() => {
        this.processSpList();
      });
    }
    processFinal() {
      switch (this._type) {
        case 1 /* COMMON */:
          const finalAwards = this._showAwards.filter((award) => this._specialAwardIds.indexOf(award.id) < 0);
          if (finalAwards.length == 0) {
            this._isShowing = false;
            this.processNext();
            return;
          }
          UIManager.ins().openForm(UIAwardTipsView, finalAwards).setCloseCallback(() => {
            this._isShowing = false;
            this.processNext();
          });
          break;
      }
    }
  };

