  // src/script/module/chineseChess/network/ChineseChessAIPlayer.ts
  var ChineseChessAIPlayer = class {
    constructor(local, color, level3, game) {
      /**
       * 补偿思考时间范围
       */
      this.thinkTimeAddRange = { min: 300, max: 1500 };
      /**
       * 思考ID
       */
      this._thinkId = 0;
      this._local = local;
      this._color = color;
      this._aiLevel = level3;
      this._game = game;
    }
    /**
     * 获取玩家颜色
     */
    get color() {
      return this._color;
    }
    /**
     * 获取玩家ai等级
     */
    get aiLevel() {
      return this._aiLevel;
    }
    /**
     * 获取象棋游戏实例
     */
    get game() {
      return this._game;
    }
    /**
     * 获取是否是本地玩家
     */
    get local() {
      return this._local;
    }
    /**
     * 改变玩家颜色
     * @param color 新颜色
     */
    changeColor(color) {
      this._color = color;
    }
    /**
     * 取消思考
     */
    cancelThinking() {
      this._thinkId++;
      Laya.timer.clearAll(this);
    }
    /**
     * 玩家回合决策
     */
    thinking() {
      if (this.game.chessManual.actived || this.game.board.currentPlayer != this.color) {
        return;
      }
      this._thinkId++;
      this._thinkingStandard();
    }
    _thinkingStandard() {
      const curThinkId = this._thinkId;
      const opStep = this.game.board.step;
      const time = Math.floor(Math.random() * (this.thinkTimeAddRange.max - this.thinkTimeAddRange.min)) + this.thinkTimeAddRange.min;
      Laya.timer.once(time, this, () => {
        this.game.aiMove(this._aiLevel, (xSrc, ySrc, xDst, yDst) => {
          if (curThinkId != this._thinkId) {
            return;
          }
          if (this.game.step != opStep) {
            return;
          }
          if (this.game.isGameOver()) {
            return;
          }
          const piece = this.game.board.getPieceAt(xSrc, ySrc);
          if (!piece) {
            console.error("AI不存在的棋子", xSrc, ySrc, xDst, yDst);
            ErrorReportManager.ins().reportLog("AI不存在的棋子");
            return;
          }
          piece.renderObject.setSelected(true);
          Laya.timer.once(300 + Math.floor(Math.random() * 800), this, () => {
            if (this.local) {
              this.game.app.onMovePiece(xSrc, ySrc, xDst, yDst, 0 /* None */, 0 /* None */);
            } else {
              ChineseChessProtoUtils.g_move_piece_c2s(
                opStep,
                {
                  x: ChineseChessNetConverter.localPieceXToNet(xSrc),
                  y: ChineseChessNetConverter.localPieceYToNet(ySrc)
                },
                {
                  x: ChineseChessNetConverter.localPieceXToNet(xDst),
                  y: ChineseChessNetConverter.localPieceYToNet(yDst)
                }
              );
            }
          });
        });
      });
    }
  };

