  var GuideTypeLine3D = class {
    constructor() {
      this.lineMeshes = [];
      // 存储多个线段来实现虚线效果
      this.segmentLength = 0.02;
      // 每段虚线的长度
      this.gapLength = 0.01;
      // 每段虚线之间的间隔
      this.lineWidth = 5e-3;
      this.lineMaterial = new Laya.UnlitMaterial();
      this.lineMaterial.lock = true;
      this.lineMaterial.albedoColor = new Laya.Color(1, 0, 0, 1);
      ;
      this.segment = Laya.PrimitiveMesh.createBox(this.lineWidth, this.lineWidth, this.segmentLength);
      this.segment.lock = true;
    }
    setComponents(node) {
      this.root = node;
    }
    onDestroy() {
      for (let mesh of this.lineMeshes) {
        if (mesh && mesh.destroy) {
          mesh.destroy();
        }
      }
      this.lineMeshes = [];
      if (this.lineMaterial) {
        this.lineMaterial.destroy();
      }
      if (this.segment) {
        this.segment.destroy();
      }
    }
    update(data) {
      this.clearSegments();
      const startPos = ChessPositionConverter.generatePosition(data.x, 9 - data.y);
      const endPos = ChessPositionConverter.generatePosition(data.x1, 9 - data.y1);
      const direction = new Laya.Vector3();
      Laya.Vector3.subtract(endPos, startPos, direction);
      const totalDistance = Laya.Vector3.scalarLength(direction);
      Laya.Vector3.normalize(direction, direction);
      const singleSegment = this.segmentLength + this.gapLength;
      const segmentCount = Math.floor(totalDistance / singleSegment);
      for (let i = 0; i < segmentCount; i++) {
        const segmentStartDistance = i * singleSegment;
        const segmentStartPos = MathUtil.tempVector3_1;
        Laya.Vector3.scale(direction, segmentStartDistance, segmentStartPos);
        Laya.Vector3.add(startPos, segmentStartPos, segmentStartPos);
        const segmentEndPos = MathUtil.tempVector3_2;
        const segmentEndDistance = segmentStartDistance + this.segmentLength;
        if (segmentEndDistance <= totalDistance) {
          Laya.Vector3.scale(direction, segmentEndDistance, segmentEndPos);
          Laya.Vector3.add(startPos, segmentEndPos, segmentEndPos);
        } else {
          segmentEndPos.setValue(endPos.x, endPos.y, endPos.z);
        }
        const segment = this.createLineSegment(segmentStartPos, segmentEndPos);
        this.lineMeshes.push(segment);
        this.root.addChild(segment);
      }
      const remainingDistance = totalDistance - segmentCount * singleSegment;
      if (remainingDistance > this.gapLength) {
        const segmentStartDistance = segmentCount * singleSegment;
        const segmentStartPos = MathUtil.tempVector3_1;
        Laya.Vector3.scale(direction, segmentStartDistance, segmentStartPos);
        Laya.Vector3.add(startPos, segmentStartPos, segmentStartPos);
        const segmentEndPos = MathUtil.tempVector3_2;
        Laya.Vector3.scale(direction, totalDistance, segmentEndPos);
        Laya.Vector3.add(startPos, segmentEndPos, segmentEndPos);
        const segment = this.createLineSegment(segmentStartPos, segmentEndPos);
        this.lineMeshes.push(segment);
        this.root.addChild(segment);
      }
    }
    createLineSegment(startPos, endPos) {
      const length = Laya.Vector3.distance(startPos, endPos);
      const segmentNode = new Laya.MeshSprite3D(this.segment);
      const meshRenderer = segmentNode.getComponent(Laya.MeshRenderer);
      meshRenderer.material = this.lineMaterial;
      const centerPos = MathUtil.tempVector3;
      Laya.Vector3.add(startPos, endPos, centerPos);
      Laya.Vector3.scale(centerPos, 0.5, centerPos);
      segmentNode.transform.position = centerPos;
      segmentNode.transform.localScaleZ = length / this.segmentLength;
      const direction = MathUtil.tempVector3;
      Laya.Vector3.subtract(endPos, startPos, direction);
      Laya.Vector3.normalize(direction, direction);
      segmentNode.transform.toDir(Laya.Vector3.ForwardRH, direction);
      return segmentNode;
    }
    clearSegments() {
      for (let mesh of this.lineMeshes) {
        if (mesh && mesh.destroy) {
          mesh.destroy();
        }
      }
      this.lineMeshes = [];
    }
    setActive(active) {
      if (this.root) {
        this.root.active = active;
      }
    }
  };

