  // src/script/module/chineseChess/gameplay/endgame/ChessEndgameHotLocalApp.ts
  var ChessEndgameHotLocalApp = class extends ChessEndgameBaseApp {
    onOpenGameView() {
      return UIManager.ins().openForm(UIChineseChessGameView);
    }
    onOpenOverlayView() {
      return UIManager.ins().openForm(UIEndgameOverlayView);
    }
    onReady() {
      const info = EndgameData.ins().endgame_start_info;
      this.game.prepareGame({
        rule: 0 /* Standard */,
        selfColor: 0 /* RED */,
        startColor: 0 /* RED */,
        fen: info.startpos,
        maxRoundTime: 0,
        maxTotalTime: 0
      });
      this.game.startGame();
    }
    onGameOver(winner) {
      if (winner == this.game.selfColor) {
        EndgameHotData.ins().markLevelPassed(EndgameData.ins().endgame_start_info.level);
      }
      UIManager.ins().openForm(UIEndgameResultView, winner, this.moveSteps, this.buildResultViewParams());
    }
    onManualQuitGame() {
      this.quitToHotSelect();
    }
    onClickBattleAction(actionId) {
      switch (actionId) {
        case 10 /* Restart */: {
          if (this.board.isMoving) {
            return;
          }
          const info = EndgameData.ins().endgame_start_info;
          if (!EndgameUtils.checkConsume(10300703 /* canju_wlrm */)) {
            return;
          }
          EndgameProtoUtils.xq_endgamechg_chg_start_c2s(4, info.level);
          break;
        }
        case 9 /* Help */:
        case 15 /* ShareManual */:
          this.shareAd(1);
          break;
        default:
          break;
      }
    }
    getShareFuncId() {
      return 10300703 /* canju_wlrm */;
    }
    getShareEndgameType() {
      return 4;
    }
    getShareTitle() {
      const info = EndgameData.ins().endgame_start_info;
      const name = FuncEntryData.ins().getFuncName(10300703 /* canju_wlrm */);
      const cfg = EndgameHotData.ins().getHotEndgameCfg(info.level);
      return `${name} ${(cfg == null ? void 0 : cfg.name) || ""}`;
    }
    quitToHotSelect() {
      GameRoomManager.ins().quitBattle();
      UIManager.ins().openForm(UIEndgameTabView, 10300703 /* canju_wlrm */);
    }
    buildResultViewParams() {
      const info = EndgameData.ins().endgame_start_info;
      const cfg = EndgameHotData.ins().getHotEndgameCfg(info.level);
      const tabConsumeCfg = EndgameData.ins().getConsumeCfg(10300703 /* canju_wlrm */);
      return {
        title: cfg ? cfg.name : "",
        showCurrency: true,
        showNextBtn: true,
        currencyText: `消耗${BagUtils.getThingHtmlIconPath(tabConsumeCfg.id, 36, 36)}${DataFormatter.formatSpecialNumber(tabConsumeCfg.num)}`,
        onClickShare: () => this.shareAd(2),
        onClickHelp: () => this.shareAd(1),
        onClickAgain: () => this.startLevel(info.level),
        onClickClose: () => this.quitToHotSelect(),
        onClickNext: () => this.startNextLevel(info.level)
      };
    }
    startNextLevel(currentLevelId) {
      const nextLevelId = this.getNextRecommendedLevelId(currentLevelId);
      if (nextLevelId <= 0) {
        TipsManager.ins().showMessageTips("关卡信息异常");
        return;
      }
      this.startLevel(nextLevelId);
    }
    /**
     * 下一关策略：
     * 1. 优先找当前关“往下”最近的未通关关卡，再找“往上”最近的未通关关卡
     * 2. 若不存在未通关（即全通），则按同样方向找最近的已通关关卡
     */
    getNextRecommendedLevelId(currentLevelId) {
      const allList = EndgameHotData.ins().getHotEndgameList();
      const allIds = allList.map((cfg) => cfg.id).sort((a, b) => a - b);
      if (allIds.length == 0) {
        return 0;
      }
      const candidateUnpassed = this.findNearestLevelIdByDirection(
        currentLevelId,
        allIds,
        (levelId) => !EndgameHotData.ins().isLevelPassed(levelId)
      );
      if (candidateUnpassed > 0) {
        return candidateUnpassed;
      }
      const candidatePassed = this.findNearestLevelIdByDirection(
        currentLevelId,
        allIds,
        (levelId) => levelId != currentLevelId && EndgameHotData.ins().isLevelPassed(levelId)
      );
      if (candidatePassed > 0) {
        return candidatePassed;
      }
      return allIds.includes(currentLevelId) ? currentLevelId : allIds[allIds.length - 1];
    }
    /**
     * 按“先往下id，再往上id”方向查找最近目标。
     */
    findNearestLevelIdByDirection(currentLevelId, sortedIds, matcher) {
      for (let i = sortedIds.length - 1; i >= 0; i--) {
        const levelId = sortedIds[i];
        if (levelId < currentLevelId && matcher(levelId)) {
          return levelId;
        }
      }
      for (let i = 0; i < sortedIds.length; i++) {
        const levelId = sortedIds[i];
        if (levelId > currentLevelId && matcher(levelId)) {
          return levelId;
        }
      }
      return 0;
    }
    startLevel(levelId) {
      const cfg = EndgameHotData.ins().getHotEndgameCfg(levelId);
      if (!cfg) {
        TipsManager.ins().showMessageTips("已是最后一关");
        return;
      }
      if (!EndgameUtils.checkConsume(10300703 /* canju_wlrm */)) {
        return;
      }
      EndgameProtoUtils.xq_endgamechg_chg_start_c2s(4, levelId);
    }
  };

